# Part 3: Exercises 81..115
exercises = [{'num': 81, 'title': 'Rate Limiting: реализация алгоритма Token Bucket на Redis', 'task': 'Rate limiter на Redis: используйте скользящее окно или token bucket для ограничения числа запросов от пользователя.', 'theory': 'Алгоритм **Token Bucket (Корзина токенов)**:\n- В корзине хранится не более $C$ (Capacity) токенов.\n- Корзина пополняется с постоянной скоростью $R$ токенов в секунду.\n- Каждый входящий запрос забирает 1 токен. Если токенов нет — HTTP 429.\n\nДля атомарности вычисления остатка токенов используется Lua-скрипт, сохраняющий в Redis Hash текущее количество токенов и таймстемп последнего пополнения.', 'step_by_step': '1. Опишите Lua-скрипт Token Bucket.\n2. Создайте метод `TakeToken(ctx, clientID) bool`.\n3. Продемонстрируйте пропуск burst-пачки и блокировку при опустошении.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"fmt"\n\t"log"\n\t"time"\n\n\t"github.com/redis/go-redis/v9"\n)\n\nconst tokenBucketLua = `\nlocal key = KEYS[1]\nlocal capacity = tonumber(ARGV[1])\nlocal refillRate = tonumber(ARGV[2]) -- токенов в секунду\nlocal now = tonumber(ARGV[3])\n\nlocal data = redis.call("HMGET", key, "tokens", "last_refill")\nlocal tokens = tonumber(data[1])\nlocal lastRefill = tonumber(data[2])\n\nif not tokens then\n    tokens = capacity\n    lastRefill = now\nelse\n    local delta = math.max(0, now - lastRefill)\n    tokens = math.min(capacity, tokens + delta * refillRate)\n    lastRefill = now\nend\n\nif tokens >= 1 then\n    tokens = tokens - 1\n    redis.call("HMSET", key, "tokens", tokens, "last_refill", lastRefill)\n    redis.call("EXPIRE", key, 300)\n    return 1\nelse\n    redis.call("HMSET", key, "tokens", tokens, "last_refill", lastRefill)\n    return 0\nend\n`\n\nfunc main() {\n\tctx := context.Background()\n\trdb := redis.NewClient(&redis.Options{Addr: "localhost:6379"})\n\tdefer rdb.Close()\n\n\tkey := "ratelimit:tb:user_42"\n\t_ = rdb.Del(ctx, key).Err()\n\n\tcapacity := 3 // максимум 3 токена\n\trefillRate := 1 // +1 токен в секунду\n\n\tfor i := 1; i <= 5; i++ {\n\t\tnowSec := time.Now().Unix()\n\t\tallowed, err := rdb.Eval(ctx, tokenBucketLua, []string{key}, capacity, refillRate, nowSec).Int()\n\t\tif err != nil {\n\t\t\tlog.Fatalf("Eval error: %v", err)\n\t\t}\n\n\t\tif allowed == 1 {\n\t\t\tfmt.Printf("Запрос %d: ✅ Разрешен\\n", i)\n\t\t} else {\n\t\t\tfmt.Printf("Запрос %d: ⛔ Отклонен (корзина пуста)\\n", i)\n\t\t}\n\t}\n}', 'note': 'Атомарный Token Bucket на Lua'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Запрос 1: ✅ Разрешен\n# Запрос 2: ✅ Разрешен\n# Запрос 3: ✅ Разрешен\n# Запрос 4: ⛔ Отклонен (корзина пуста)\n# Запрос 5: ⛔ Отклонен (корзина пуста)'}], 'under_the_hood': 'Token Bucket позволяет обрабатывать кратковременные всплески трафика (bursts) до размера `capacity`, плавно ограничивая постоянную среднюю скорость на уровне `refillRate`.', 'pitfalls': 'Вычислять пополнение токенов отдельным фоновым таймером в Go. Нагрузка вырастет на миллионы ключей. Всегда рассчитывайте пополнение "лениво" (on-demand) в момент входящего запроса по формуле разницы времени `now - lastRefill`.', 'bigtech_interview': '**Вопрос с собеседования:** «В чем преимущество Token Bucket перед Fixed Window?»\n**Ответ:** Fixed Window допускает двукратное превышение лимита на стыке минут (100 запросов в 11:59:59 и 100 запросов в 12:00:01). Token Bucket гарантирует строгое ограничение пополнения и исключает пиковые перегрузки микросервиса.'}, {'num': 82, 'title': 'Хранение сессий пользователей в Redis Hash со скользящим TTL', 'task': '**Сессии пользователей**: Храните `session_id` в HttpOnly Cookie, а саму сессию (user_id, roles, preferences) — в Redis Hash с TTL. Реализуйте механизм "продления" сессии при активности.', 'theory': 'Паттерн **Sliding Session (Скользящая сессия)**:\n- При авторизации создается криптографически стойкий `session_id` (UUIDv4).\n- В Redis Hash сохраняются атрибуты сессии: `user_id`, `role`, `email`.\n- Устанавливается базовый TTL (например 30 минут).\n- При каждом входящем HTTP-запросе сервис читает данные сессии и отправляет `EXPIRE session:id 1800`, продлевая жизнь сессии еще на 30 минут активности.', 'step_by_step': '1. Создайте сессию через `HSet`.\n2. Реализуйте middleware продления сессии через `Expire`.\n3. Убедитесь в обновлении срока жизни.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"fmt"\n\t"log"\n\t"time"\n\n\t"github.com/redis/go-redis/v9"\n)\n\ntype SessionManager struct {\n\trdb        *redis.Client\n\tsessionTTL time.Duration\n}\n\nfunc (sm *SessionManager) CreateSession(ctx context.Context, sessionID string, userID int64, role string) error {\n\tkey := fmt.Sprintf("session:%s", sessionID)\n\tpipe := sm.rdb.TxPipeline()\n\tpipe.HSet(ctx, key, "user_id", userID, "role", role, "created_at", time.Now().Unix())\n\tpipe.Expire(ctx, key, sm.sessionTTL)\n\t_, err := pipe.Exec(ctx)\n\treturn err\n}\n\nfunc (sm *SessionManager) ValidateAndTouch(ctx context.Context, sessionID string) (map[string]string, error) {\n\tkey := fmt.Sprintf("session:%s", sessionID)\n\n\t// Получаем поля сессии\n\tdata, err := sm.rdb.HGetAll(ctx, key).Result()\n\tif err != nil {\n\t\treturn nil, err\n\t}\n\tif len(data) == 0 {\n\t\treturn nil, fmt.Errorf("сессия истекла или не существует")\n\t}\n\n\t// Продлеваем TTL (Sliding Session)\n\t_ = sm.rdb.Expire(ctx, key, sm.sessionTTL).Err()\n\n\treturn data, nil\n}\n\nfunc main() {\n\tctx := context.Background()\n\trdb := redis.NewClient(&redis.Options{Addr: "localhost:6379"})\n\tdefer rdb.Close()\n\n\tsm := &SessionManager{rdb: rdb, sessionTTL: 30 * time.Minute}\n\tsessID := "tok_uuid_9941_secure"\n\n\t// 1. Создаем\n\t_ = sm.CreateSession(ctx, sessID, 105, "editor")\n\tfmt.Println("Сессия пользователя #105 успешно создана")\n\n\t// 2. Обрабатываем входящий запрос\n\tsessData, err := sm.ValidateAndTouch(ctx, sessID)\n\tif err != nil {\n\t\tlog.Fatalf("Ошибка сессии: %v", err)\n\t}\n\n\tttl, _ := rdb.TTL(ctx, "session:"+sessID).Result()\n\tfmt.Printf("Сессия валидна: User=%s, Role=%s | Оставшийся TTL продлен до: %v\\n",\n\t\tsessData["user_id"], sessData["role"], ttl)\n}', 'note': 'Управление скользящими сессиями через Redis Hash'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Сессия пользователя #105 успешно создана\n# Сессия валидна: User=105, Role=editor | Оставшийся TTL продлен до: 30m0s'}], 'under_the_hood': 'Использование Redis Hashes для сессий позволяет мгновенно менять статус пользователя (например отозвать права администратора: `HSET session:id role user`), не инвалидируя всю авторизационную cookie-сессию.', 'pitfalls': 'Хранить чувствительные токены (например пароли или секретные ключи API) в открытом виде в значении сессии. Храните только идентификатор пользователя и метаданные прав.', 'bigtech_interview': '**Вопрос с собеседования:** «Как реализовать "Выйти на всех устройствах" (Single Logout) при хранении сессий в Redis?»\n**Ответ:** Создать дополнительный Set `user:105:sessions`, в который добавлять каждый сгенерированный `session_id`. При нажатии "Выйти со всех устройств" бэкенд считывает список через `SMEMBERS`, удаляет все ключи `session:<id>` через `UNLINK` и очищает сам сет.'}, {'num': 83, 'title': 'Паттерн Write-Through: сквозная синхронизация базы данных и кэша', 'task': 'Реализуй **Write-Through cache**: `CreateUser` сначала пишет в БД, затем инвалидирует/обновляет кеш. `UpdateUser` — то же. Покажи консистентность.', 'theory': 'В паттерне **Write-Through** запись данных всегда проходит через кэширующий слой:\n1. Приложение вызывает метод `CreateUser` или `UpdateUser`.\n2. Репозиторий атомарно обновляет основную базу данных (PostgreSQL).\n3. Затем сразу обновляет (или инвалидирует) запись в Redis.\nЭто гарантирует, что последующие запросы на чтение не увидят устаревшие данные.', 'step_by_step': '1. Создайте структуру `UserWriteThroughRepository`.\n2. Реализуйте методы `CreateUser` и `UpdateUser`.\n3. Продемонстрируйте обновление кэша при модификации данных.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"encoding/json"\n\t"fmt"\n\t"log"\n\t"time"\n\n\t"github.com/redis/go-redis/v9"\n)\n\ntype User struct {\n\tID    int64  `json:"id"`\n\tEmail string `json:"email"`\n}\n\ntype UserRepo struct {\n\trdb *redis.Client\n}\n\nfunc (r *UserRepo) CreateUser(ctx context.Context, u User) error {\n\t// 1. Запись в PostgreSQL (INSERT INTO users ...)\n\tfmt.Printf("[PostgreSQL] INSERT INTO users VALUES (%d, \'%s\')\\n", u.ID, u.Email)\n\n\t// 2. Синхронное обновление кэша\n\tkey := fmt.Sprintf("user:%d", u.ID)\n\tdata, _ := json.Marshal(u)\n\treturn r.rdb.Set(ctx, key, data, 10*time.Minute).Err()\n}\n\nfunc (r *UserRepo) UpdateUser(ctx context.Context, u User) error {\n\t// 1. Обновление в PostgreSQL (UPDATE users ...)\n\tfmt.Printf("[PostgreSQL] UPDATE users SET email = \'%s\' WHERE id = %d\\n", u.Email, u.ID)\n\n\t// 2. Инвалидация/перезапись в Redis\n\tkey := fmt.Sprintf("user:%d", u.ID)\n\tdata, _ := json.Marshal(u)\n\treturn r.rdb.Set(ctx, key, data, 10*time.Minute).Err()\n}\n\nfunc main() {\n\tctx := context.Background()\n\trdb := redis.NewClient(&redis.Options{Addr: "localhost:6379"})\n\tdefer rdb.Close()\n\n\trepo := &UserRepo{rdb: rdb}\n\tuser := User{ID: 501, Email: "initial@mail.ru"}\n\n\t// Создание\n\t_ = repo.CreateUser(ctx, user)\n\n\t// Обновление\n\tuser.Email = "updated@mail.ru"\n\t_ = repo.UpdateUser(ctx, user)\n\n\t// Чтение из кэша\n\tcached, err := rdb.Get(ctx, "user:501").Result()\n\tif err != nil {\n\t\tlog.Fatalf("Get error: %v", err)\n\t}\n\n\tfmt.Printf("[Redis] Актуальное состояние в кэше: %s\\n", cached)\n}', 'note': 'Паттерн Write-Through с поддержанием строгой консистентности'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [PostgreSQL] INSERT INTO users VALUES (501, \'initial@mail.ru\')\n# [PostgreSQL] UPDATE users SET email = \'updated@mail.ru\' WHERE id = 501\n# [Redis] Актуальное состояние в кэше: {"id":501,"email":"updated@mail.ru"}'}], 'under_the_hood': 'Write-Through увеличивает задержку операций записи (поскольку нужно дождаться ответа и от БД, и от Redis), но гарантирует отсутствие промахов (Cache Miss) при последующих чтениях.', 'pitfalls': 'Конкурентные перезаписи при двух параллельных `UpdateUser`. Если запрос А и запрос Б выполняются одновременно, в Redis может записаться устаревшая версия. Для исключения гонок чаще выбирают инвалидацию (`DEL`).', 'bigtech_interview': '**Вопрос с собеседования:** «В чем отличие Write-Through от Write-Behind (Write-Back)?»\n**Ответ:** При **Write-Through** запись в БД и кэш происходит синхронно до ответа клиенту. При **Write-Behind** сервис мгновенно сохраняет данные ТОЛЬКО в Redis и сразу отвечает клиенту, а фоновый воркер асинхронно сбрасывает данные в PostgreSQL пачками (batch insert). Write-Behind дает колоссальную скорость записи, но несет риск потери данных при сбое кэша до сброса в БД.'}, {'num': 84, 'title': 'Мгновенное извлечение профиля при Cache Hit', 'task': 'Ищем юзера в Redis. Если есть — возвращаем (Cache Hit).', 'theory': 'Быстрый путь выполнения (Happy Path): проверка наличия ключа и возврат десериализованного объекта без каких-либо обращений к реляционной БД.', 'step_by_step': '1. Заполните профиль пользователя в Redis.\n2. Проверьте наличие ключа.\n3. Десериализуйте и верните данные за субмиллисекундное время.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"encoding/json"\n\t"fmt"\n\t"log"\n\n\t"github.com/redis/go-redis/v9"\n)\n\ntype UserProfile struct {\n\tID       int64  `json:"id"`\n\tNickname string `json:"nickname"`\n}\n\nfunc main() {\n\tctx := context.Background()\n\trdb := redis.NewClient(&redis.Options{Addr: "localhost:6379"})\n\tdefer rdb.Close()\n\n\tkey := "profile:user:99"\n\tdata, _ := json.Marshal(UserProfile{ID: 99, Nickname: "GoDeveloper"})\n\t_ = rdb.Set(ctx, key, data, 0).Err()\n\n\t// Извлечение\n\traw, err := rdb.Get(ctx, key).Bytes()\n\tif err != nil {\n\t\tlog.Fatalf("Cache hit failure: %v", err)\n\t}\n\n\tvar p UserProfile\n\t_ = json.Unmarshal(raw, &p)\n\tfmt.Printf("[CACHE HIT] Профиль пользователя успешно загружен: %+v\\n", p)\n}', 'note': 'Обработка Cache Hit сценария'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод: [CACHE HIT] Профиль пользователя успешно загружен: {ID:99 Nickname:GoDeveloper}'}], 'under_the_hood': 'При попадании в кэш ответ возвращается за 200–500 микросекунд, минуя дисковый стек и планировщик транзакций реляционной СУБД.', 'pitfalls': 'Аллокация новых буферов на каждый вызов JSON. В высоконагруженных шлюзах используют fastjson или sonic.', 'bigtech_interview': '**Вопрос с собеседования:** «Какое соотношение Cache Hit Ratio считается здоровым для продакшена?»\n**Ответ:** Для типичного контентного бэкенда нормальным считается Hit Ratio на уровне 85–98%. Если Hit Ratio падает ниже 70%, это свидетельствует о проблемах: короткий TTL, недостаточный размер RAM, частая инвалидация или Cache Stampede.'}, {'num': 85, 'title': 'Read-Through кэш, инвалидация и эффект Eventual Consistency', 'task': 'Реализуй **Read-Through cache** с TTL: данные в кеше живут 5 минут. При обновлении в БД — `CacheDelete` (invalidate). Покажи **eventual consistency**: между `UPDATE` и `CacheDelete` читатели видят stale-данные.', 'theory': 'В распределенных системах между моментом коммита `UPDATE` в базе данных и моментом физического удаления ключа в Redis (`DEL`) существует временное окно (race window) длительностью от нескольких микросекунд до десятков миллисекунд.\nВ этот интервал параллельные читатели видят старое значение (**Stale Read**). Это фундаментальное свойство моделей согласованности в конечном счете (**Eventual Consistency**).', 'step_by_step': '1. Создайте модель данных с кэшем.\n2. Продемонстрируйте окно рассинхронизации между UPDATE и инвалидацией.\n3. Покажите восстановление консистентности после вызова `CacheDelete`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"fmt"\n\t"log"\n\t"time"\n\n\t"github.com/redis/go-redis/v9"\n)\n\ntype CustomerStore struct {\n\trdb        *redis.Client\n\tcurrentDB  string // эмуляция базы данных\n}\n\nfunc (s *CustomerStore) UpdateDBWithSimulatedLag(ctx context.Context, id int, newValue string) {\n\tkey := fmt.Sprintf("customer:%d", id)\n\n\t// 1. Обновляем БД\n\ts.currentDB = newValue\n\tfmt.Printf("[DB COMMIT] База данных обновлена: \'%s\'\\n", newValue)\n\n\t// Имитация сетевой задержки до инвалидации кэша\n\ttime.Sleep(50 * time.Millisecond)\n\n\t// 2. Инвалидируем кэш\n\t_ = s.rdb.Del(ctx, key).Err()\n\tfmt.Println("[CACHE INVALIDATE] Ключ удален из Redis")\n}\n\nfunc main() {\n\tctx := context.Background()\n\trdb := redis.NewClient(&redis.Options{Addr: "localhost:6379"})\n\tdefer rdb.Close()\n\n\tstore := &CustomerStore{rdb: rdb, currentDB: "Премиум клиент"}\n\tkey := "customer:10"\n\n\t// Заполним кэш старым значением\n\t_ = rdb.Set(ctx, key, "Базовый клиент", 5*time.Minute).Err()\n\n\t// Запускаем обновление в фоне\n\tgo store.UpdateDBWithSimulatedLag(ctx, 10, "VIP клиент")\n\n\t// Читатель 1 читает сразу во время лага инвалидации\n\ttime.Sleep(10 * time.Millisecond)\n\tstaleVal, _ := rdb.Get(ctx, key).Result()\n\tfmt.Printf("⚠️  [Eventual Consistency] Читатель видит stale-данные: \'%s\'\\n", staleVal)\n\n\t// Читатель 2 читает после завершения инвалидации\n\ttime.Sleep(80 * time.Millisecond)\n\t_, err := rdb.Get(ctx, key).Result()\n\tfmt.Printf("✅  [Consistent Read] Кэш пуст (err=%v), читатель идет в БД за \'%s\'\\n", err, store.currentDB)\n}', 'note': 'Демонстрация окна Eventual Consistency и stale-чтения'}, {'filename': 'Терминал', 'lang': 'bash', 'code': "go run main.go\n# Вывод:\n# [DB COMMIT] База данных обновлена: 'VIP клиент'\n# ⚠️  [Eventual Consistency] Читатель видит stale-данные: 'Базовый клиент'\n# [CACHE INVALIDATE] Ключ удален из Redis\n# ✅  [Consistent Read] Кэш пуст (err=redis: nil), читатель идет в БД за 'VIP клиент'"}], 'under_the_hood': 'Теорема CAP и компромиссы PACELC: использование кэша выбирает Высокую Доступность (Availability) и Низкую Задержку (Latency) ценой слабой согласованности (Eventual Consistency). Для подавляющего большинства бизнес-сценариев (лента новостей, профили, каталог товаров) это абсолютно допустимо.', 'pitfalls': 'Использовать кэш-слой для балансов счетов или критических финансовых блокировок без строгой транзакционной изоляции.', 'bigtech_interview': '**Вопрос с собеседования:** «Как свести к минимуму окно Stale Read при обновлении данных?»\n**Ответ:** 1. Использовать паттерн Double Delete (удалить ключ из кэша до коммита и еще раз асинхронно через 500 мс после коммита). 2. Применять репликацию CDC (Change Data Capture) из бинарных логов СУБД для мгновенного удаления ключей.'}, {'num': 86, 'title': 'Установка срока жизни на поля хэша: эмуляция TTL против HEXPIRE (Redis 7.4+)', 'task': '**Expiration**: Установи TTL на конкретное поле внутри Hash (до Redis 7.2 это было невозможно через стандартные команды. Используй структуру данных в виде строки JSON с `SET ... EX`, чтобы сэмулировать TTL для одного поля, или обнови до Redis 7.2+ и используй `HEXPIRE`).', 'theory': 'Исторически команда `EXPIRE` работала только на уровне ключа целиком.\nВ современных версиях:\n1. **Современный путь (Redis 7.4+):** появилась нативная команда `HEXPIRE key seconds FIELDS numfields field [field ...]`.\n2. **Классический переносимый паттерн:** хранить время экспирации каждого поля прямо в хэше (например поле `field:expire_at` с Unix-таймстемпом) и проверять валидность в Go/Lua, либо использовать отдельные строковые ключи с TTL.', 'step_by_step': '1. Реализуйте структуру хэша с таймстемпом экспирации поля.\n2. Проверьте валидность поля по текущему системному времени.\n3. Продемонстрируйте очистку просроченного поля через `HDEL`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"fmt"\n\t"log"\n\t"strconv"\n\t"time"\n\n\t"github.com/redis/go-redis/v9"\n)\n\ntype HashFieldTTLStore struct {\n\trdb *redis.Client\n}\n\n// SetFieldWithTTL сохраняет поле и таймстемп его протухания\nfunc (s *HashFieldTTLStore) SetFieldWithTTL(ctx context.Context, hashKey, field, value string, ttl time.Duration) error {\n\texpireAt := time.Now().Add(ttl).UnixMilli()\n\texpField := field + ":expires_at"\n\n\treturn s.rdb.HSet(ctx, hashKey, field, value, expField, expireAt).Err()\n}\n\n// GetFieldWithTTL возвращает значение только если TTL поля еще не истек\nfunc (s *HashFieldTTLStore) GetFieldWithTTL(ctx context.Context, hashKey, field string) (string, bool, error) {\n\texpField := field + ":expires_at"\n\n\tvals, err := s.rdb.HMGet(ctx, hashKey, field, expField).Result()\n\tif err != nil {\n\t\treturn "", false, err\n\t}\n\n\tif vals[0] == nil || vals[1] == nil {\n\t\treturn "", false, nil\n\t}\n\n\texpMs, _ := strconv.ParseInt(vals[1].(string), 10, 64)\n\tif time.Now().UnixMilli() > expMs {\n\t\t// Поле протухло — лениво удаляем его\n\t\t_ = s.rdb.HDel(ctx, hashKey, field, expField).Err()\n\t\treturn "", false, nil\n\t}\n\n\treturn vals[0].(string), true, nil\n}\n\nfunc main() {\n\tctx := context.Background()\n\trdb := redis.NewClient(&redis.Options{Addr: "localhost:6379"})\n\tdefer rdb.Close()\n\n\tstore := &HashFieldTTLStore{rdb: rdb}\n\tkey := "user:session:meta"\n\t_ = rdb.Del(ctx, key).Err()\n\n\t// Устанавливаем временный OTP код с TTL 1.5 секунды\n\t_ = store.SetFieldWithTTL(ctx, key, "otp_code", "7749", 1500*time.Millisecond)\n\n\t// Читаем сразу\n\tval, ok, _ := store.GetFieldWithTTL(ctx, key, "otp_code")\n\tfmt.Printf("1. Чтение сразу: значение=\'%s\', валидно=%v\\n", val, ok)\n\n\t// Ждем истечения срока\n\tfmt.Println("Ждем 2 секунды...")\n\ttime.Sleep(2 * time.Second)\n\n\t// Читаем после истечения\n\tval, ok, _ = store.GetFieldWithTTL(ctx, key, "otp_code")\n\tfmt.Printf("2. Чтение после паузы: валидно=%v (поле просрочено и очищено!)\\n", ok)\n}', 'note': 'Эмуляция TTL для отдельных полей внутри Hash'}, {'filename': 'Терминал', 'lang': 'bash', 'code': "go run main.go\n# Вывод:\n# 1. Чтение сразу: значение='7749', валидно=true\n# Ждем 2 секунды...\n# 2. Чтение после паузы: валидно=false (поле просрочено и очищено!)"}], 'under_the_hood': 'Такой паттерн ленивой проверки (Lazy Expiration) широко применяется в продакшене, так как обеспечивает 100% обратную совместимость с любыми версиями Redis (включая старые корпоративные инсталляции Redis 5/6).', 'pitfalls': 'Накапливать просроченные поля без очистки, если к ним больше никогда не обращаются. Если хэш содержит много редких полей, требуется периодический проход через `HSCAN` для удаления просроченных полей.', 'bigtech_interview': '**Вопрос с собеседования:** «Каковы новые команды работы со сроком жизни полей хэша в Redis 7.4+?»\n**Ответ:** Появились команды `HEXPIRE` (в секундах), `HPEXPIRE` (в миллисекундах), `HEXPIREAT` (по таймстемпу) и `HTTL` / `HPTTL` для проверки оставшегося времени жизни конкретного поля.'}, {'num': 87, 'title': 'Идиоматичная распределенная блокировка: SETNX, критическая секция и Lua-unlock', 'task': 'Распределённая блокировка: захватите ключ с `SETNX` и TTL, выполните критическую секцию, освободите блокировку.', 'theory': 'Классический паттерн распределенного мьютекса:\n1. Генерация уникального `lockValue` (UUID / случайный токен).\n2. Захват блокировки: `rdb.SetNX(ctx, lockKey, lockValue, ttl)`.\n3. Исполнение критической секции кода.\n4. Освобождение через Lua-скрипт (удаление `DEL` только если значение совпадает с `lockValue`).', 'step_by_step': '1. Захватите блокировку.\n2. Выполните критическую секцию.\n3. Безопасно освободите блокировку через Lua в блоке `defer`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"crypto/rand"\n\t"encoding/hex"\n\t"fmt"\n\t"log"\n\t"time"\n\n\t"github.com/redis/go-redis/v9"\n)\n\nconst safeUnlockLua = `\nif redis.call("get", KEYS[1]) == ARGV[1] then\n    return redis.call("del", KEYS[1])\nelse\n    return 0\nend\n`\n\nfunc executeCriticalSection(ctx context.Context, rdb *redis.Client, lockKey string) error {\n\t// 1. Уникальный токен для этого вызова\n\ttokenBytes := make([]byte, 16)\n\t_, _ = rand.Read(tokenBytes)\n\tlockValue := hex.EncodeToString(tokenBytes)\n\tlockTTL := 5 * time.Second\n\n\t// 2. Атомарный захват через SetNX\n\tacquired, err := rdb.SetNX(ctx, lockKey, lockValue, lockTTL).Result()\n\tif err != nil {\n\t\treturn fmt.Errorf("redis error: %w", err)\n\t}\n\tif !acquired {\n\t\treturn fmt.Errorf("ресурс заблокирован другим процессом")\n\t}\n\n\t// 3. Безопасное освобождение в defer\n\tdefer func() {\n\t\tres, err := rdb.Eval(context.Background(), safeUnlockLua, []string{lockKey}, lockValue).Result()\n\t\tif err != nil {\n\t\t\tlog.Printf("Ошибка снятия блокировки: %v", err)\n\t\t} else {\n\t\t\tfmt.Printf("Лок освобожден (результат Lua: %v)\\n", res)\n\t\t}\n\t}()\n\n\t// 4. Критическая секция\n\tfmt.Println("🔒 Критическая секция выполняется эксклюзивно...")\n\ttime.Sleep(200 * time.Millisecond)\n\tfmt.Println("✅ Критическая секция успешно завершена!")\n\n\treturn nil\n}\n\nfunc main() {\n\tctx := context.Background()\n\trdb := redis.NewClient(&redis.Options{Addr: "localhost:6379"})\n\tdefer rdb.Close()\n\n\tkey := "lock:balance_transfer"\n\t_ = rdb.Del(ctx, key).Err()\n\n\tif err := executeCriticalSection(ctx, rdb, key); err != nil {\n\t\tlog.Fatalf("Ошибка: %v", err)\n\t}\n}', 'note': 'Безопасный захват и освобождение распределенной блокировки'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# 🔒 Критическая секция выполняется эксклюзивно...\n# ✅ Критическая секция успешно завершена!\n# Лок освобожден (результат Lua: 1)'}], 'under_the_hood': 'Атомарность `SetNX` обеспечивается флагом `NX` в RESP-протоколе `SET key val NX EX 5`. Сервер гарантирует, что ключ будет записан только если он ранее отсутствовал, без необходимости предварительного `GET`.', 'pitfalls': 'Использовать простой `rdb.Del(ctx, lockKey)` без проверки значения токена: если работа затянулась дольше TTL, лок истечет, его перехватит другой воркер, а первый воркер своим `DEL` снимет ЧУЖОЙ лок!', 'bigtech_interview': '**Вопрос с собеседования:** «Почему в defer безопасного снятия лока используется `context.Background()`, а не входящий `ctx`?»\n**Ответ:** Если входящий `ctx` был отменен по клиентскому таймауту запроса (например, клиент нажал отмену в браузере), вызов `rdb.Eval(ctx, ...)` завершится с ошибкой `context canceled` и лок останется висеть в Redis до истечения полного TTL. Использование чистого `context.Background()` гарантирует отправку команды снятия блокировки.'}, {'num': 88, 'title': 'Пакетные запросы: бенчмарк 1000 последовательных Set против Pipeline', 'task': '**Пакетные запросы (Pipeline)**: Если вам нужно отправить много команд в Redis, отправка каждой команды по отдельности создает накладные расходы на сетевые запросы (RTT). Напишите код, который записывает 1000 ключей в Redis двумя способами:\n    * Обычными последовательными вызовами `client.Set`.\n    * С использованием `client.Pipeline()` (когда все команды собираются в пакет и отправляются за один сетевой запрос).\n    Замерьте и сравните время выполнения обоих вариантов.', 'theory': 'Сравнение последовательных синхронных вызовов и конвейеризации — классический бенчмарк, наглядно демонстрирующий влияние Round-Trip Time (RTT) на производительность распределенных приложений.', 'step_by_step': '1. Запишите 1000 ключей в цикле через `rdb.Set()`.\n2. Замерьте время через `time.Since()`.\n3. Запишите 1000 ключей через `pipe := rdb.Pipeline()`.\n4. Замерьте время и рассчитайте коэффициент ускорения.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"fmt"\n\t"log"\n\t"time"\n\n\t"github.com/redis/go-redis/v9"\n)\n\nfunc main() {\n\tctx := context.Background()\n\trdb := redis.NewClient(&redis.Options{Addr: "localhost:6379"})\n\tdefer rdb.Close()\n\n\tconst count = 1000\n\n\t// 1. Последовательные вызовы\n\tstartSeq := time.Now()\n\tfor i := 0; i < count; i++ {\n\t\tkey := fmt.Sprintf("seq:%d", i)\n\t\t_ = rdb.Set(ctx, key, "val", 5*time.Minute).Err()\n\t}\n\tseqDuration := time.Since(startSeq)\n\n\t// 2. Пакетная запись через Pipeline\n\tstartPipe := time.Now()\n\tpipe := rdb.Pipeline()\n\tfor i := 0; i < count; i++ {\n\t\tkey := fmt.Sprintf("pipe:%d", i)\n\t\tpipe.Set(ctx, key, "val", 5*time.Minute)\n\t}\n\t_, err := pipe.Exec(ctx)\n\tif err != nil {\n\t\tlog.Fatalf("Pipeline exec error: %v", err)\n\t}\n\tpipeDuration := time.Since(startPipe)\n\n\tfmt.Printf("1. Последовательно (1000 вызовов): %v\\n", seqDuration)\n\tfmt.Printf("2. Через Pipeline  (1000 вызовов): %v\\n", pipeDuration)\n\tfmt.Printf("🚀 Pipeline быстрее в %.1f раз!\\n", float64(seqDuration)/float64(pipeDuration))\n}', 'note': 'Бенчмарк сетевой конвейеризации'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# 1. Последовательно (1000 вызовов): 68.4ms\n# 2. Через Pipeline  (1000 вызовов): 3.2ms\n# 🚀 Pipeline быстрее в 21.4 раз!'}], 'under_the_hood': 'Даже на локальном хосте (loopback 127.0.0.1) накладные расходы на системные вызовы ядра `epoll_wait`/`sendmsg` создают задержку. В реальной сети ЦОД с задержкой 0.5–2 мс ускорение от Pipeline достигает **100–300 раз**!', 'pitfalls': 'Забывать вызывать `pipe.Exec(ctx)`: команды останутся в буфере клиента Go и вообще не уйдут на сервер.', 'bigtech_interview': '**Вопрос с собеседования:** «Чем Pipeline отличается от MSET?»\n**Ответ:** `MSET` — это специализированная команда для атомарной установки множества строк. Она не поддерживает разные типы операций и не может ставить индивидуальный TTL на каждый ключ. Pipeline — это универсальный сетевой механизм пакетирования любых произвольных команд протокола RESP.'}, {'num': 89, 'title': 'Rate Limiter на фиксированном окне через Pipeline: атомарный INCR и EXPIRE', 'task': 'Реализуй **Rate Limiter** через Redis: `SLIDE_WINDOW`. Ключ = `rate_limit:ip:minute:YYYY-MM-DD-HH-MM`. `INCR` + `EXPIRE 60`. Если счётчик > limit — `429 Too Many Requests`. Используй pipeline для атомарности `INCR` + `EXPIRE`.', 'theory': 'Паттерн **Fixed Window Rate Limiter** с поминутным ключом:\n- Ключ формируется с текущей минутой: `rate:ip:2026-09-03-14-50`.\n- В одном пайплайне вызывается `INCR key` и `EXPIRE key 60`.\n- Если возвращенный счетчик превышает порог, запрос отклоняется (429).\nБлагодаря суффиксу минуты старые ключи автоматически отмирают без накопления памяти.', 'step_by_step': '1. Сформируйте ключ с временной меткой текущей минуты.\n2. Отправьте `Incr` и `Expire` в пайплайне.\n3. Проверьте значение счетчика.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"fmt"\n\t"log"\n\t"time"\n\n\t"github.com/redis/go-redis/v9"\n)\n\ntype MinuteRateLimiter struct {\n\trdb   *redis.Client\n\tlimit int64\n}\n\nfunc (rl *MinuteRateLimiter) Allow(ctx context.Context, ip string) (bool, int64, error) {\n\tcurrentMinute := time.Now().UTC().Format("2006-01-02-15-04")\n\tkey := fmt.Sprintf("rate_limit:%s:%s", ip, currentMinute)\n\n\tpipe := rl.rdb.Pipeline()\n\tincrCmd := pipe.Incr(ctx, key)\n\tpipe.Expire(ctx, key, 70*time.Second) // 70 сек с запасом на дрейф времени\n\t_, err := pipe.Exec(ctx)\n\tif err != nil {\n\t\treturn false, 0, err\n\t}\n\n\tcount := incrCmd.Val()\n\treturn count <= rl.limit, count, nil\n}\n\nfunc main() {\n\tctx := context.Background()\n\trdb := redis.NewClient(&redis.Options{Addr: "localhost:6379"})\n\tdefer rdb.Close()\n\n\tlimiter := &MinuteRateLimiter{rdb: rdb, limit: 3}\n\tip := "192.168.1.55"\n\n\tfor i := 1; i <= 5; i++ {\n\t\tallowed, count, err := limiter.Allow(ctx, ip)\n\t\tif err != nil {\n\t\t\tlog.Fatalf("Error: %v", err)\n\t\t}\n\n\t\tif allowed {\n\t\t\tfmt.Printf("Запрос %d (счетчик=%d): 200 OK\\n", i, count)\n\t\t} else {\n\t\t\tfmt.Printf("Запрос %d (счетчик=%d): 429 Too Many Requests\\n", i, count)\n\t\t}\n\t}\n}', 'note': 'Поминутный Rate Limiter на базе Pipeline'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Запрос 1 (счетчик=1): 200 OK\n# Запрос 2 (счетчик=2): 200 OK\n# Запрос 3 (счетчик=3): 200 OK\n# Запрос 4 (счетчик=4): 429 Too Many Requests\n# Запрос 5 (счетчик=5): 429 Too Many Requests'}], 'under_the_hood': 'Использование Pipeline здесь критично: отправка `INCR` и `EXPIRE` двумя независимыми сетевыми запросами создавала бы риск: если после `INCR` сервис упадет, ключ останется без TTL и зависнет в памяти навсегда.', 'pitfalls': 'Краевой эффект: клиент может отправить 100 запросов в 14:50:59 и еще 100 запросов в 14:51:01, сделав 200 запросов за 2 секунды. Для строгого контроля используйте скользящее окно (Sliding Window Log).', 'bigtech_interview': '**Вопрос с собеседования:** «Почему в `EXPIRE` указано 70 секунд, а не ровно 60?»\n**Ответ:** Небольшой запас (buffer time) в 10 секунд гарантирует, что ключ не исчезнет до окончания текущей минуты из-за возможной легкой рассинхронизации системных часов серверов (NTP skew).'}, {'num': 90, 'title': 'Точный Sliding Window Log Rate Limiter на Sorted Set (ZSET)', 'task': "Реализуй **Rate Limiter (sliding window log)**: `ZADD` timestamp'ов, `ZREMRANGEBYSCORE` старых (старше window), `ZCARD` для подсчёта. Более точный, но дороже по памяти.", 'theory': 'Алгоритм **Sliding Window Log**:\n- Элементы ZSET: уникальные метки времени входящих запросов.\n- Очистка устаревших: `ZREMRANGEBYSCORE key 0 (now - window)`.\n- Подсчет: `ZCARD key`.\n- Добавление текущего: `ZADD key now unique_request_id`.\nЭтот алгоритм абсолютно исключает всплески на границах окон, обеспечивая 100% честное ограничение.', 'step_by_step': '1. Напишите пайплайн очистки и подсчета.\n2. Проверьте число запросов в скользящем интервале.\n3. Протестируйте поведение.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"fmt"\n\t"log"\n\t"time"\n\n\t"github.com/redis/go-redis/v9"\n)\n\ntype SlidingLogLimiter struct {\n\trdb    *redis.Client\n\tlimit  int64\n\twindow time.Duration\n}\n\nfunc (s *SlidingLogLimiter) Allow(ctx context.Context, key string) (bool, error) {\n\tnow := time.Now().UnixNano()\n\twindowStart := now - s.window.Nanoseconds()\n\n\tpipe := s.rdb.TxPipeline()\n\t// 1. Удаляем все запросы, сделанные раньше текущего скользящего окна\n\tpipe.ZRemRangeByScore(ctx, key, "0", fmt.Sprintf("%d", windowStart))\n\t// 2. Считаем сколько запросов осталось в окне\n\tcardCmd := pipe.ZCard(ctx, key)\n\t// 3. Добавляем текущий запрос\n\tpipe.ZAdd(ctx, key, redis.Z{Score: float64(now), Member: fmt.Sprintf("%d", now)})\n\tpipe.Expire(ctx, key, s.window*2)\n\t_, err := pipe.Exec(ctx)\n\tif err != nil {\n\t\treturn false, err\n\t}\n\n\treturn cardCmd.Val() < s.limit, nil\n}\n\nfunc main() {\n\tctx := context.Background()\n\trdb := redis.NewClient(&redis.Options{Addr: "localhost:6379"})\n\tdefer rdb.Close()\n\n\tlimiter := &SlidingLogLimiter{\n\t\trdb:    rdb,\n\t\tlimit:  2,\n\t\twindow: 1 * time.Second,\n\t}\n\n\tkey := "limiter:sliding:user_10"\n\t_ = rdb.Del(ctx, key).Err()\n\n\t// 1. Два запроса подряд\n\ta1, _ := limiter.Allow(ctx, key)\n\ta2, _ := limiter.Allow(ctx, key)\n\tfmt.Printf("Запрос 1: %v, Запрос 2: %v\\n", a1, a2)\n\n\t// 2. Третий запрос в ту же секунду должен быть заблокирован\n\ta3, _ := limiter.Allow(ctx, key)\n\tfmt.Printf("Запрос 3 (в ту же секунду): %v (должен быть false)\\n", a3)\n\n\t// 3. Ждем 1.1 секунды\n\ttime.Sleep(1100 * time.Millisecond)\n\ta4, _ := limiter.Allow(ctx, key)\n\tfmt.Printf("Запрос 4 (после сдвига окна): %v (окно очистилось)\\n", a4)\n}', 'note': 'Высокоточный лимитер на базе ZSET'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Запрос 1: true, Запрос 2: true\n# Запрос 3 (в ту же секунду): false (должен быть false)\n# Запрос 4 (после сдвига окна): true (окно очистилось)'}], 'under_the_hood': 'Использование Unix наносекунд гарантирует уникальность значения `Member` в ZSET даже при конкурентных запросах, пришедших в пределах одной миллисекунды.', 'pitfalls': 'Расход памяти: при лимите в 10 000 запросов в минуту ZSET будет хранить 10 000 элементов на одного пользователя.', 'bigtech_interview': '**Вопрос с собеседования:** «Как оптимизировать расход памяти Sliding Window без потери точности?»\n**Ответ:** Использовать гибридный алгоритм **Sliding Window Counter** (взвешенное среднее двух счетчиков):\n$$\\text{Requests} = \\text{Count}(\\text{current\\_minute}) + \\text{Count}(\\text{prev\\_minute}) \\times (1 - \\text{progress})$$\nОн требует всего два обычных строковых счетчика в Redis (около 100 байт памяти) и дает точность более 99%.'}, {'num': 91, 'title': 'Мокирование внешнего источника данных при Cache Miss', 'task': 'Если нет (Cache Miss) — идем в PostgreSQL (сделай мок функции).', 'theory': 'При тестировании и разработке уровня кэширования обращение к базе данных изолируется за интерфейсом с моком, позволяя проверить правильность логики кэширования без реального подключения к PostgreSQL.', 'step_by_step': '1. Создайте интерфейс `UserLoader` с мок-реализацией.\n2. Проверьте обращение к моку при отсутствии ключа в Redis.\n3. Убедитесь в сохранении загруженных данных в кэш.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"errors"\n\t"fmt"\n\t"log"\n\t"time"\n\n\t"github.com/redis/go-redis/v9"\n)\n\ntype UserLoader interface {\n\tLoadUserFromDB(ctx context.Context, id int64) (string, error)\n}\n\ntype MockPostgresLoader struct {\n\tCallsCount int\n}\n\nfunc (m *MockPostgresLoader) LoadUserFromDB(ctx context.Context, id int64) (string, error) {\n\tm.CallsCount++\n\treturn fmt.Sprintf("User#%d:Dmitry", id), nil\n}\n\ntype CachedUserService struct {\n\trdb    *redis.Client\n\tloader UserLoader\n}\n\nfunc (s *CachedUserService) GetUser(ctx context.Context, id int64) (string, error) {\n\tkey := fmt.Sprintf("u:cache:%d", id)\n\n\tval, err := s.rdb.Get(ctx, key).Result()\n\tif err == nil {\n\t\treturn val, nil\n\t}\n\n\tif errors.Is(err, redis.Nil) {\n\t\t// Cache Miss: идем в мок базы данных\n\t\tdata, err := s.loader.LoadUserFromDB(ctx, id)\n\t\tif err != nil {\n\t\t\treturn "", err\n\t\t}\n\t\t_ = s.rdb.Set(ctx, key, data, 5*time.Minute).Err()\n\t\treturn data, nil\n\t}\n\n\treturn "", err\n}\n\nfunc main() {\n\tctx := context.Background()\n\trdb := redis.NewClient(&redis.Options{Addr: "localhost:6379"})\n\tdefer rdb.Close()\n\n\tmock := &MockPostgresLoader{}\n\tsvc := &CachedUserService{rdb: rdb, loader: mock}\n\n\t_ = rdb.Del(ctx, "u:cache:12").Err()\n\n\t// 1. Первый вызов (Cache Miss)\n\tu1, _ := svc.GetUser(ctx, 12)\n\t// 2. Второй вызов (Cache Hit)\n\tu2, _ := svc.GetUser(ctx, 12)\n\n\tfmt.Printf("Результат 1: %s\\n", u1)\n\tfmt.Printf("Результат 2: %s\\n", u2)\n\tfmt.Printf("Вызовов базы данных (мока): %d (ожидалось ровно 1)\\n", mock.CallsCount)\n}', 'note': 'Тестирование Cache Miss логики с моком базы данных'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Результат 1: User#12:Dmitry\n# Результат 2: User#12:Dmitry\n# Вызовов базы данных (мока): 1 (ожидалось ровно 1)'}], 'under_the_hood': 'Паттерн интерфейсов в Go позволяет полностью изолировать логику кэширования от конкретного SQL-драйвера (pgx, database/sql), обеспечивая 100% покрытие юнит-тестами.', 'pitfalls': 'Тестировать методы кэширования без сброса ключа перед каждым тестом (эффект грязного состояния).', 'bigtech_interview': '**Вопрос с собеседования:** «Какую библиотеку мокирования рекомендуется использовать в тестах Go?»\n**Ответ:** `uber-go/mock` (ранее `golang/mock / gomock`) или встроенную библиотеку `testify/mock`. Для Redis-слоя лучшим стандартом является `miniredis`.'}, {'num': 92, 'title': 'Каверзный кейс: анализ задержки RTT при записи 1000 ключей через Pipeline', 'task': '**[Каверзный кейс — Пайплайны]**: Запиши 1000 ключей в Redis. Сначала сделай это в цикле 1000 раз через `client.Set`. Затем сделай то же самое через `client.Pipeline` (одним сетевым запросом). Измерь время выполнения `time.Since()` и оцени разницу.', 'theory': 'Почему Pipeline ускоряет работу в десятки раз?\nВ последовательном коде поток Go блокируется на ожидании чтения ответа сокета (`syscall.Read`). Ядро Linux переводит горутину в состояние ожидания, что порождает переключения контекста GMP-планировщика. В Pipeline все 1000 команд формируются в один сетевой буфер и отправляются за один вызов `write`.', 'step_by_step': '1. Замерьте суммарное время 1000 вызовов `client.Set`.\n2. Замерьте суммарное время `client.Pipeline`.\n3. Рассчитайте метрику Round-Trip Latency.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"fmt"\n\t"time"\n\n\t"github.com/redis/go-redis/v9"\n)\n\nfunc main() {\n\tctx := context.Background()\n\trdb := redis.NewClient(&redis.Options{Addr: "localhost:6379"})\n\tdefer rdb.Close()\n\n\tconst N = 1000\n\n\t// Способ А: Последовательно\n\tt0 := time.Now()\n\tfor i := 0; i < N; i++ {\n\t\t_ = rdb.Set(ctx, fmt.Sprintf("bench:seq:%d", i), i, 0).Err()\n\t}\n\tseqTime := time.Since(t0)\n\n\t// Способ Б: Pipeline\n\tt1 := time.Now()\n\tpipe := rdb.Pipeline()\n\tfor i := 0; i < N; i++ {\n\t\tpipe.Set(ctx, fmt.Sprintf("bench:pipe:%d", i), i, 0)\n\t}\n\t_, _ = pipe.Exec(ctx)\n\tpipeTime := time.Since(t1)\n\n\tfmt.Printf("Последовательно: %v (среднее %.3f ms на операцию)\\n",\n\t\tseqTime, float64(seqTime.Milliseconds())/float64(N))\n\tfmt.Printf("Pipeline:        %v (среднее %.3f ms на батч)\\n",\n\t\tpipeTime, float64(pipeTime.Milliseconds()))\n\tfmt.Printf("Итоговый прирост производительности: %.1fx\\n", float64(seqTime)/float64(pipeTime))\n}', 'note': 'Сравнение затрат RTT между последовательным выполнением и Pipeline'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Последовательно: 71.2ms (среднее 0.071 ms на операцию)\n# Pipeline:        3.4ms (среднее 3.000 ms на батч)\n# Итоговый прирост производительности: 20.9x'}], 'under_the_hood': 'Разница во времени обусловлена не сложностью вычислений на CPU сервера Redis (Redis выполняет `SET` за десятки наносекунд), а физической задержкой сетевого стека операционной системы (TCP ACK, sliding window, context switches).', 'pitfalls': 'Использовать Pipeline для бесконечно большого числа команд. Если команд больше 10 000, нарезайте их на батчи по 1000 штук.', 'bigtech_interview': '**Вопрос с собеседования:** «Каковы накладные расходы по оперативной памяти у Redis при выполнении огромного Pipeline на 100 000 команд?»\n**Ответ:** Redis обязан сформировать и держать в оперативной памяти ответы на все 100 000 команд в клиентском буфере вывода (`client-output-buffer-limit`). Это может вызвать резкий скачок потребления RAM и даже принудительное отключение клиента по превышению лимита буфера.'}, {'num': 93, 'title': 'Хранение пользовательской сессии с автоматическим продлением TTL (Touch)', 'task': 'Реализуйте сохранение сессии пользователя в Redis с TTL, обновляемым при каждом запросе.', 'theory': 'Метод `rdb.Expire(ctx, key, ttl)` сбрасывает обратный отсчет таймера экспирации. В протоколе Redis это эквивалентно обновлению поля `expires` в словаре ключей. Это позволяет поддерживать сессию активной до тех пор, пока пользователь взаимодействует с сервисом.', 'step_by_step': '1. Сохраните сессию с TTL 15 минут.\n2. Проверьте оставшийся TTL.\n3. Вызовите функцию обновления активности `TouchSession`.\n4. Убедитесь, что TTL восстановился до полных 15 минут.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"fmt"\n\t"log"\n\t"time"\n\n\t"github.com/redis/go-redis/v9"\n)\n\ntype SessionService struct {\n\trdb *redis.Client\n\tttl time.Duration\n}\n\nfunc (s *SessionService) Touch(ctx context.Context, sessionID string) error {\n\tkey := fmt.Sprintf("session:%s", sessionID)\n\trefreshed, err := s.rdb.Expire(ctx, key, s.ttl).Result()\n\tif err != nil {\n\t\treturn err\n\t}\n\tif !refreshed {\n\t\treturn fmt.Errorf("сессия не существует")\n\t}\n\treturn nil\n}\n\nfunc main() {\n\tctx := context.Background()\n\trdb := redis.NewClient(&redis.Options{Addr: "localhost:6379"})\n\tdefer rdb.Close()\n\n\tsvc := &SessionService{rdb: rdb, ttl: 15 * time.Minute}\n\tsessKey := "session:token_9012"\n\n\t// Создаем сессию\n\t_ = rdb.Set(ctx, sessKey, "user_id_44", 15*time.Minute).Err()\n\n\t// Имитируем запрос через 2 секунды\n\ttime.Sleep(100 * time.Millisecond)\n\n\t// Продлеваем сессию\n\tif err := svc.Touch(ctx, "token_9012"); err != nil {\n\t\tlog.Fatalf("Touch error: %v", err)\n\t}\n\n\tremaining, _ := rdb.TTL(ctx, sessKey).Result()\n\tfmt.Printf("Сессия успешно продлена! Новый TTL: %v\\n", remaining)\n}', 'note': 'Автоматическое продление срока жизни сессии'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод: Сессия успешно продлена! Новый TTL: 15m0s'}], 'under_the_hood': 'Сложность команды `EXPIRE` составляет строго $O(1)$. Redis просто перезаписывает 64-битное целое число в хэш-таблице `db.expires` без изменения самого значения ключа.', 'pitfalls': 'Вызывать `Touch` при каждом статическом запросе (загрузка css, js, картинок). Обновляйте сессию только при реальных API-запросах.', 'bigtech_interview': '**Вопрос с собеседования:** «Что возвращает команда `EXPIRE key seconds`?»\n**Ответ:** Целое число `1`, если таймаут был успешно установлен/обновлен, и `0`, если указанный ключ не существует.'}, {'num': 94, 'title': 'Интеграционное тестирование с Testcontainers-go для Redis', 'task': '**Testcontainers (Redis)**: Сделайте то же самое для Redis.', 'theory': 'Библиотека `testcontainers-go` — золотой стандарт интеграционного тестирования в Go:\n1. Запускает реальный Docker-контейнер с официальным образом `redis:7-alpine`.\n2. Выделяет случайный свободный порт хоста (исключая конфликты портов при параллельном запуске тестов в CI/CD).\n3. Дожидается готовности контейнера (LogConsumer или Exec проверка `redis-cli ping`).\n4. Автоматически уничтожает контейнер после завершения теста через Ryuk.', 'step_by_step': '1. Опишите запуск `testcontainers.GenericContainer`.\n2. Подключитесь через `redis.NewClient`.\n3. Выполните проверку `Ping`.\n4. Остановите контейнер.', 'code_blocks': [{'filename': 'redis_test.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"fmt"\n\t"testing"\n\t"time"\n\n\t"github.com/redis/go-redis/v9"\n\t"github.com/testcontainers/testcontainers-go"\n\t"github.com/testcontainers/testcontainers-go/wait"\n)\n\nfunc TestRedisIntegration(t *testing.T) {\n\tctx := context.Background()\n\n\t// Конфигурация контейнера Redis\n\treq := testcontainers.ContainerRequest{\n\t\tImage:        "redis:7-alpine",\n\t\tExposedPorts: []string{"6379/tcp"},\n\t\tWaitingFor:   wait.ForLog("Ready to accept connections").WithStartupTimeout(30 * time.Second),\n\t}\n\n\tredisC, err := testcontainers.GenericContainer(ctx, testcontainers.GenericContainerRequest{\n\t\tContainerRequest: req,\n\t\tStarted:          true,\n\t})\n\tif err != nil {\n\t\tt.Skipf("Docker недоступен в среде окружения: %v", err)\n\t\treturn\n\t}\n\tdefer func() {\n\t\t_ = redisC.Terminate(ctx)\n\t}()\n\n\t// Получаем динамический порт хоста\n\tendpoint, err := redisC.Endpoint(ctx, "")\n\tif err != nil {\n\t\tt.Fatalf("Failed to get endpoint: %v", err)\n\t}\n\n\trdb := redis.NewClient(&redis.Options{Addr: endpoint})\n\tdefer rdb.Close()\n\n\t// Проверяем реальную работоспособность\n\tpong, err := rdb.Ping(ctx).Result()\n\tif err != nil || pong != "PONG" {\n\t\tt.Fatalf("Ping failed: %v", err)\n\t}\n\n\tfmt.Printf("✅ Интеграционный тест Redis успешно прошел на адресе: %s\\n", endpoint)\n}', 'note': 'Поднятие изолированного инстанса Redis в Testcontainers'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go test -v redis_test.go\n# Вывод:\n# === RUN   TestRedisIntegration\n# ✅ Интеграционный тест Redis успешно прошел на адресе: 127.0.0.1:32789\n# --- PASS: TestRedisIntegration (1.85s)\n# PASS'}], 'under_the_hood': 'Testcontainers использует Unix-сокет `/var/run/docker.sock` для управления жизненным циклом контейнеров через официальный Docker API SDK. Контейнер Moby Ryuk гарантирует сборку мусора даже при аварийном завершении тестов (`kill -9`).', 'pitfalls': 'Поднимать новый контейнер на каждый юнит-тест. Запуск контейнера занимает 1–2 секунды. В больших тестовых наборах один контейнер запускают в `TestMain(m *testing.M)` и переиспользуют между всеми тестами пакета, очищая данные командой `FLUSHALL`.', 'bigtech_interview': '**Вопрос с собеседования:** «В каких случаях стоит использовать `miniredis`, а в каких — Testcontainers?»\n**Ответ:** `miniredis` идеален для быстрых юнит-тестов (стартует за микросекунды, не требует Docker). Testcontainers необходим для проверки специфичного поведения: Lua-скрипты, Redis Streams, Consumer Groups, проверка кластерных редиректов или работа с модулями RedisJSON / RediSearch.'}, {'num': 95, 'title': 'Полноценный Session Store: HSet, HGetAll, Expire и HDel при Logout', 'task': 'Реализуй **Session Store** в Redis: `HSET session:abc123 user_id 123 expires 1234567890`. При каждом запросе — `HGETALL` + проверка TTL. `HDEL` при logout. Используй `EXPIRE` на весь ключ.', 'theory': 'Промышленный интерфейс Session Store объединяет:\n- `SaveSession(sessionID, data, ttl)`\n- `GetSession(sessionID)`\n- `DestroySession(sessionID)` — удаление при логауте.', 'step_by_step': '1. Создайте структуру `RedisSessionStore`.\n2. Реализуйте полный жизненный цикл: логин, проверка, логаут.\n3. Продемонстрируйте завершение сессии.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"fmt"\n\t"log"\n\t"time"\n\n\t"github.com/redis/go-redis/v9"\n)\n\ntype SessionStore struct {\n\trdb *redis.Client\n}\n\nfunc (s *SessionStore) Login(ctx context.Context, token string, userID int64, ttl time.Duration) error {\n\tkey := "session:" + token\n\tpipe := s.rdb.TxPipeline()\n\tpipe.HSet(ctx, key, "user_id", userID, "logged_at", time.Now().Unix())\n\tpipe.Expire(ctx, key, ttl)\n\t_, err := pipe.Exec(ctx)\n\treturn err\n}\n\nfunc (s *SessionStore) Check(ctx context.Context, token string) (map[string]string, error) {\n\tkey := "session:" + token\n\tdata, err := s.rdb.HGetAll(ctx, key).Result()\n\tif err != nil {\n\t\treturn nil, err\n\t}\n\tif len(data) == 0 {\n\t\treturn nil, fmt.Errorf("сессия недействительна")\n\t}\n\treturn data, nil\n}\n\nfunc (s *SessionStore) Logout(ctx context.Context, token string) error {\n\tkey := "session:" + token\n\treturn s.rdb.Del(ctx, key).Err()\n}\n\nfunc main() {\n\tctx := context.Background()\n\trdb := redis.NewClient(&redis.Options{Addr: "localhost:6379"})\n\tdefer rdb.Close()\n\n\tstore := &SessionStore{rdb: rdb}\n\ttoken := "abc123_session_cookie"\n\n\t// 1. Вход в систему\n\t_ = store.Login(ctx, token, 8841, 1*time.Hour)\n\tfmt.Println("1. Пользователь 8841 успешно авторизован")\n\n\t// 2. Проверка сессии\n\tsess, err := store.Check(ctx, token)\n\tif err != nil {\n\t\tlog.Fatalf("Check error: %v", err)\n\t}\n\tfmt.Printf("2. Данные сессии: UserID=%s\\n", sess["user_id"])\n\n\t// 3. Выход из системы (Logout)\n\t_ = store.Logout(ctx, token)\n\tfmt.Println("3. Выполнен Logout")\n\n\t// 4. Повторная проверка\n\t_, err = store.Check(ctx, token)\n\tfmt.Printf("4. Проверка после Logout: %v (доступ закрыт)\\n", err)\n}', 'note': 'Реализация хранилища сессий с логаутом'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# 1. Пользователь 8841 успешно авторизован\n# 2. Данные сессии: UserID=8841\n# 3. Выполнен Logout\n# 4. Проверка после Logout: сессия недействительна (доступ закрыт)'}], 'under_the_hood': 'Для моментального логаута вызов `DEL` освобождает ключ за микросекунды, гарантируя мгновенный отзыв доступа на всех серверах кластера.', 'pitfalls': 'Хранить сессии только в оперативной памяти инстанса Go: при перезапуске пода (Rolling Update в K8s) все пользователи разлогинятся. Redis обеспечивает централизованное состояние.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему сессии в Redis предпочтительнее JWT без состояния (Stateless JWT)?»\n**Ответ:** Stateless JWT невозможно мгновенно отозвать при компрометации (утечке токена) или блокировке пользователя администратором до истечения его `exp`. Хранение сессий в Redis дает мгновенный отзыв доступа (Revocation) в реальном времени.'}, {'num': 96, 'title': 'Безопасный Distributed Lock с валидацией UUID через Lua-скрипт', 'task': '**Распределенная блокировка (Distributed Lock)**: В распределенных системах мьютексы внутри программы не работают на уровне нескольких серверов. Реализуйте распределенную блокировку на Redis:\n    * Захват блокировки: вызов команды `SetNX` (Set if Not Exists) с определенным ключом, уникальным токеном (UUID) в качестве значения и TTL 5 секунд.\n    * Если блокировка успешно захвачена — выполните работу.\n    * Освобождение блокировки: напишите Lua-скрипт (или выполните команду), который безопасно удаляет ключ только в том случае, если значение в Redis по-прежнему совпадает с вашим UUID (чтобы случайно не удалить чужую блокировку, если ваша истекла по таймауту).', 'theory': 'Критическая уязвимость наивной блокировки:\n1. Процесс А захватывает ключ `lock` на 5 секунд.\n2. Процесс А завис на долгом I/O на 6 секунд.\n3. Redis удаляет ключ по TTL.\n4. Процесс Б захватывает ключ `lock`.\n5. Процесс А просыпается и выполняет `DEL lock`, удаляя блокировку Процесса Б!\n6. Процесс В тоже захватывает лок. Критическая секция нарушена.\n\n**Решение:** освобождать замок Lua-скриптом, проверяющим соответствие уникального токена владения.', 'step_by_step': '1. Сгенерируйте уникальный UUID.\n2. Вызовите `rdb.SetNX(ctx, key, uuid, 5*time.Second)`.\n3. Освободите замок через Lua-скрипт проверки UUID.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"fmt"\n\t"log"\n\t"time"\n\n\t"github.com/google/uuid"\n\t"github.com/redis/go-redis/v9"\n)\n\nconst unlockScript = `\nif redis.call("get", KEYS[1]) == ARGV[1] then\n    return redis.call("del", KEYS[1])\nelse\n    return 0\nend\n`\n\nfunc main() {\n\tctx := context.Background()\n\trdb := redis.NewClient(&redis.Options{Addr: "localhost:6379"})\n\tdefer rdb.Close()\n\n\tlockKey := "distributed:resource:payout"\n\tlockToken := uuid.New().String()\n\tlockTTL := 5 * time.Second\n\n\t// 1. Захват\n\tok, err := rdb.SetNX(ctx, lockKey, lockToken, lockTTL).Result()\n\tif err != nil || !ok {\n\t\tlog.Fatalf("Не удалось захватить распределенный лок: %v", err)\n\t}\n\tfmt.Printf("🔒 Лок захвачен токеном: %s\\n", lockToken)\n\n\t// 2. Исполнение работы\n\ttime.Sleep(100 * time.Millisecond)\n\n\t// 3. Безопасное освобождение через Lua\n\tres, err := rdb.Eval(ctx, unlockScript, []string{lockKey}, lockToken).Int()\n\tif err != nil {\n\t\tlog.Fatalf("Ошибка Lua unlock: %v", err)\n\t}\n\n\tif res == 1 {\n\t\tfmt.Println("🔓 Блокировка успешно и безопасно снята владельцем!")\n\t} else {\n\t\tfmt.Println("⚠️ Замок уже принадлежал другому владельцу или протух!")\n\t}\n}', 'note': 'Атомарное освобождение блокировки только ее владельцем'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# 🔒 Лок захвачен токеном: 4c3118c7-d4fa-4fc6-b258-3d149021c385\n# 🔓 Блокировка успешно и безопасно снята владельцем!'}], 'under_the_hood': 'Скрипт `if redis.call("get", KEYS[1]) == ARGV[1] then return redis.call("del", KEYS[1])` исключает состояние гонки (Race Condition) между операциями проверки и удаления, так как выполняется в одном такте Event Loop Redis.', 'pitfalls': 'Использовать предсказуемые токены (например `lock_val = "1"`). Токен обязан быть криптографически стойким и уникальным для каждого отдельного инстанса и вызова.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему проверка `GET` и последующий `DEL` из Go-кода без Lua опасны?»\n**Ответ:** Между вызовом `GET` и вызовом `DEL` по сети проходит время. В этот микроскопический промежуток ключ может протухнуть по TTL, и его успеет перехватить другой воркер. Вызов `DEL` удалит уже чужой замок.'}, {'num': 97, 'title': 'Мульти-канальный Pub/Sub обмен сообщениями в реальном времени', 'task': 'Реализуй **Pub/Sub** через Redis: `rdb.Subscribe(ctx, "channel1", "channel2")`. В горутине читай `sub.Channel()`. Другой клиент публикует через `rdb.Publish(ctx, "channel1", "message")`. Покажи real-time messaging.', 'theory': 'Метод `rdb.Subscribe` позволяет оформить подписку сразу на несколько каналов. Входящий Go-канал `pubsub.Channel()` доставляет структуры `*redis.Message`, где поле `msg.Channel` указывает точное имя топика, из которого поступило событие.', 'step_by_step': '1. Подпишитесь на `channel1` и `channel2`.\n2. Запустите чтение в горутине.\n3. Опубликуйте сообщения в оба топика.\n4. Убедитесь в доставке сообщений.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"fmt"\n\t"log"\n\t"sync"\n\t"time"\n\n\t"github.com/redis/go-redis/v9"\n)\n\nfunc main() {\n\tctx := context.Background()\n\trdb := redis.NewClient(&redis.Options{Addr: "localhost:6379"})\n\tdefer rdb.Close()\n\n\tvar wg sync.WaitGroup\n\twg.Add(1)\n\n\t// Подписка на несколько каналов сразу\n\tpubsub := rdb.Subscribe(ctx, "channel1", "channel2")\n\tdefer pubsub.Close()\n\n\t// Ждем подтверждения подписки\n\t_, err := pubsub.Receive(ctx)\n\tif err != nil {\n\t\tlog.Fatalf("Receive failed: %v", err)\n\t}\n\n\tgo func() {\n\t\twg.Done()\n\t\tch := pubsub.Channel()\n\t\tfor msg := range ch {\n\t\t\tfmt.Printf("📬 Принято из [%s]: %s\\n", msg.Channel, msg.Payload)\n\t\t\tif msg.Payload == "done" {\n\t\t\t\tbreak\n\t\t\t}\n\t\t}\n\t}()\n\n\twg.Wait()\n\ttime.Sleep(100 * time.Millisecond)\n\n\t// Публикуем в разные каналы\n\t_ = rdb.Publish(ctx, "channel1", "Сообщение для первого канала").Err()\n\t_ = rdb.Publish(ctx, "channel2", "Событие для второго канала").Err()\n\t_ = rdb.Publish(ctx, "channel1", "done").Err()\n\n\ttime.Sleep(200 * time.Millisecond)\n}', 'note': 'Подписка на несколько каналов одновременно'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# 📬 Принято из [channel1]: Сообщение для первого канала\n# 📬 Принято из [channel2]: Событие для второго канала\n# 📬 Принято из [channel1]: done'}], 'under_the_hood': 'Сервер Redis поддерживает структуру `server.pubsub_channels` — хэш-таблицу, где ключами являются имена каналов, а значениями — связные списки клиентских структур дескрипторов сокетов. Публикация обходит список и выполняет запись в TCP-буфер за время $O(N)$, где $N$ — число подписчиков канала.', 'pitfalls': 'Забивание внутреннего Go-канала `pubsub.Channel()`: если горутина читает медленнее, чем поступают сообщения, буфер канала переполнится.', 'bigtech_interview': '**Вопрос с собеседования:** «В чем отличие `SUBSCRIBE` от `PSUBSCRIBE`?»\n**Ответ:** `SUBSCRIBE` подписывается на точные имена топиков. `PSUBSCRIBE pattern` подписывается по маске с glob-паттерном (например `news.*`, `metrics:orders:*`), получая сообщения из всех каналов, соответствующих шаблону.'}, {'num': 98, 'title': 'Кэширование результата выборки из БД с TTL 10 минут', 'task': 'Кладем результат из БД в Redis с TTL = 10 минут.', 'theory': 'Установка фиксированного TTL в 10 минут (`10 * time.Minute`) — классический компромисс между снижением нагрузки на дисковую базу данных и свежестью данных.\nДля предотвращения одновременного истечения тысяч ключей (Cache Avalanche) к фиксированному TTL рекомендуется добавлять случайный джиттер (Jitter):\n$$\\text{TTL} = \\text{baseTTL} + \\text{rand}(0, 60)\\text{ секунд}$$', 'step_by_step': '1. Получите результат тяжелого запроса к БД.\n2. Сериализуйте в JSON.\n3. Сохраните в Redis с TTL 10 минут.\n4. Проверьте сохраненный ключ.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"encoding/json"\n\t"fmt"\n\t"log"\n\t"time"\n\n\t"github.com/redis/go-redis/v9"\n)\n\ntype HeavyReport struct {\n\tReportID int64  `json:"report_id"`\n\tData     string `json:"data"`\n}\n\nfunc main() {\n\tctx := context.Background()\n\trdb := redis.NewClient(&redis.Options{Addr: "localhost:6379"})\n\tdefer rdb.Close()\n\n\tkey := "report:monthly:financial:2026_09"\n\treport := HeavyReport{ReportID: 101, Data: "Оборот: 50 000 000 руб."}\n\n\t// Сериализуем\n\tbytes, err := json.Marshal(report)\n\tif err != nil {\n\t\tlog.Fatalf("Marshal error: %v", err)\n\t}\n\n\t// Сохраняем в Redis с TTL 10 минут\n\tttl := 10 * time.Minute\n\tif err := rdb.Set(ctx, key, bytes, ttl).Err(); err != nil {\n\t\tlog.Fatalf("Set error: %v", err)\n\t}\n\n\tactualTTL, _ := rdb.TTL(ctx, key).Result()\n\tfmt.Printf("Отчет успешно сохранен в кэш! Ключ: %s\\n", key)\n\tfmt.Printf("Фактический TTL в Redis: %v\\n", actualTTL)\n}', 'note': 'Кэширование тяжелых отчетов с TTL 10 минут'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Отчет успешно сохранен в кэш! Ключ: report:monthly:financial:2026_09\n# Фактический TTL в Redis: 10m0s'}], 'under_the_hood': 'Redis сохраняет таймстемп истечения в миллисекундах (`UNIX timestamp MS`). При фоновой репликации на слейвы мастер передает точную абсолютную команду `PEXPIREAT`, чтобы исключить дрейф времени из-за сетевой задержки репликации.', 'pitfalls': 'Выставлять одинаковый TTL для всех ключей при ночном прогреве кэша. Ровно через 10 минут все ключи протухнут в одну секунду, вызвав Cache Avalanche.', 'bigtech_interview': '**Вопрос с собеседования:** «Что такое Cache Jitter и как его рассчитывать в Go?»\n**Ответ:** Jitter — это случайное отклонение, добавляемое к базовому TTL:\n`jitter := time.Duration(rand.Intn(60)) * time.Second; ttl := 10*time.Minute + jitter`. Это размывает момент экспирации ключей по времени, предотвращая лавинообразную нагрузку на БД.'}, {'num': 99, 'title': 'Pub/Sub: непрерывный подписчик на канал news и издатель сообщений', 'task': '**[Pub/Sub]**: Напиши две программы (или две горутины). Первая подписывается на канал `client.Subscribe(ctx, "news")` и читает сообщения в бесконечном цикле. Вторая публикует сообщение `client.Publish(ctx, "news", "Hello")`.', 'theory': 'Паттерн Pub/Sub позволяет реализовать мгновенную шину уведомлений (Event Bus) между различными микросервисами в архитектуре бэкенда.', 'step_by_step': '1. Запустите первую горутину с `Subscribe(ctx, "news")`.\n2. Читайте сообщения в цикле `for msg := range pubsub.Channel()`.\n3. Запустите вторую горутину с `Publish(ctx, "news", "Hello")`.\n4. Зафиксируйте прием сообщения.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"fmt"\n\t"log"\n\t"sync"\n\t"time"\n\n\t"github.com/redis/go-redis/v9"\n)\n\nfunc main() {\n\tctx := context.Background()\n\trdb := redis.NewClient(&redis.Options{Addr: "localhost:6379"})\n\tdefer rdb.Close()\n\n\ttopic := "news"\n\tvar wg sync.WaitGroup\n\twg.Add(1)\n\n\t// 1. Горутина-подписчик\n\tgo func() {\n\t\tpubsub := rdb.Subscribe(ctx, topic)\n\t\tdefer pubsub.Close()\n\n\t\t// Подтверждение подписки\n\t\t_, err := pubsub.Receive(ctx)\n\t\tif err != nil {\n\t\t\tlog.Fatalf("Receive failed: %v", err)\n\t\t}\n\t\twg.Done()\n\n\t\tch := pubsub.Channel()\n\t\tfor msg := range ch {\n\t\t\tfmt.Printf("📬 [Подписчик] Получена новость: %s\\n", msg.Payload)\n\t\t\tif msg.Payload == "stop" {\n\t\t\t\tbreak\n\t\t\t}\n\t\t}\n\t}()\n\n\twg.Wait()\n\ttime.Sleep(100 * time.Millisecond)\n\n\t// 2. Горутина-издатель\n\tfmt.Println("🚀 [Издатель] Публикуем \'Hello\'...")\n\t_ = rdb.Publish(ctx, topic, "Hello").Err()\n\ttime.Sleep(100 * time.Millisecond)\n\n\t_ = rdb.Publish(ctx, topic, "stop").Err()\n\ttime.Sleep(100 * time.Millisecond)\n}', 'note': 'Синхронизация горутин через канал Pub/Sub'}, {'filename': 'Терминал', 'lang': 'bash', 'code': "go run main.go\n# Вывод:\n# 🚀 [Издатель] Публикуем 'Hello'...\n# 📬 [Подписчик] Получена новость: Hello\n# 📬 [Подписчик] Получена новость: stop"}], 'under_the_hood': 'Подписчик слушает TCP сокет в режиме блокирующего чтения. Когда издатель отправляет `PUBLISH`, сервер Redis немедленно записывает RESP-фрейм `message\\r\\nnews\\r\\nHello\\r\\n` в сокет каждого подписчика без сохранения в дисковый буфер.', 'pitfalls': 'Ожидать повторной доставки при разрыве TCP соединения. Если подписчик отключился на 1 секунду, все отправленные в эту секунду новости безвозвратно теряются.', 'bigtech_interview': '**Вопрос с собеседования:** «Какова задержка доставки сообщения в Redis Pub/Sub?»\n**Ответ:** Задержка составляет менее 1 миллисекунды (субмиллисекундная доставка в пределах локальной сети ЦОД), так как сообщение передается по уже открытым готовым TCP-сокетам без дискового I/O.'}, {'num': 100, 'title': 'Хранение реестра WebSocket-соединений в распределенном Redis Set', 'task': 'Используйте Redis для хранения состояния WebSocket-соединений (связь user_id с идентификаторами сокетов).', 'theory': 'В распределенных веб-приложениях пользователь может быть подключен одновременно с нескольких вкладок или устройств к разным инстансам бэкенда:\n- Ключ в Redis: `ws:user:<user_id>:connections` (структура Set).\n- При подключении клиента: `SADD ws:user:<id>:connections "<server_ip>:<socket_uuid>"`.\n- При отключении: `SREM ws:user:<id>:connections "<server_ip>:<socket_uuid>"`.\n- Для отправки личного сообщения сервис считывает адреса сокетов и шлет команду через Redis Pub/Sub на нужные ноды.', 'step_by_step': '1. Создайте реестр сокетов `WebSocketRegistry`.\n2. Зарегистрируйте два подключения одного пользователя (телефон и ноутбук).\n3. Прочитайте активные сокеты через `SMembers`.\n4. Удалите разорванное соединение через `SRem`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"fmt"\n\t"log"\n\t"time"\n\n\t"github.com/redis/go-redis/v9"\n)\n\ntype WebSocketRegistry struct {\n\trdb *redis.Client\n}\n\nfunc (r *WebSocketRegistry) userSocketsKey(userID int64) string {\n\treturn fmt.Sprintf("ws:user:%d:connections", userID)\n}\n\nfunc (r *WebSocketRegistry) Register(ctx context.Context, userID int64, serverID, socketID string) error {\n\tconnID := fmt.Sprintf("%s:%s", serverID, socketID)\n\tkey := r.userSocketsKey(userID)\n\n\tpipe := r.rdb.TxPipeline()\n\tpipe.SAdd(ctx, key, connID)\n\tpipe.Expire(ctx, key, 24*time.Hour) // Защитный TTL\n\t_, err := pipe.Exec(ctx)\n\treturn err\n}\n\nfunc (r *WebSocketRegistry) Unregister(ctx context.Context, userID int64, serverID, socketID string) error {\n\tconnID := fmt.Sprintf("%s:%s", serverID, socketID)\n\treturn r.rdb.SRem(ctx, r.userSocketsKey(userID), connID).Err()\n}\n\nfunc (r *WebSocketRegistry) GetActiveConnections(ctx context.Context, userID int64) ([]string, error) {\n\treturn r.rdb.SMembers(ctx, r.userSocketsKey(userID)).Result()\n}\n\nfunc main() {\n\tctx := context.Background()\n\trdb := redis.NewClient(&redis.Options{Addr: "localhost:6379"})\n\tdefer rdb.Close()\n\n\tregistry := &WebSocketRegistry{rdb: rdb}\n\tuserID := int64(774)\n\t_ = rdb.Del(ctx, registry.userSocketsKey(userID)).Err()\n\n\t// 1. Пользователь подключился с браузера на сервере 1\n\t_ = registry.Register(ctx, userID, "pod_backend_1", "sock_browser_abc")\n\n\t// 2. Пользователь подключился со смартфона на сервере 2\n\t_ = registry.Register(ctx, userID, "pod_backend_2", "sock_mobile_xyz")\n\n\t// 3. Получаем список всех активных соединений\n\tconns, err := registry.GetActiveConnections(ctx, userID)\n\tif err != nil {\n\t\tlog.Fatalf("Error: %v", err)\n\t}\n\tfmt.Printf("Активные сокеты пользователя #%d (%d шт.):\\n", userID, len(conns))\n\tfor _, c := range conns {\n\t\tfmt.Printf("  • %s\\n", c)\n\t}\n\n\t// 4. Смартфон отключился\n\t_ = registry.Unregister(ctx, userID, "pod_backend_2", "sock_mobile_xyz")\n\tconnsAfter, _ := registry.GetActiveConnections(ctx, userID)\n\tfmt.Printf("\\nПосле отключения смартфона осталось: %v\\n", connsAfter)\n}', 'note': 'Распределенный реестр WebSocket соединений'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Активные сокеты пользователя #774 (2 шт.):\n#   • pod_backend_1:sock_browser_abc\n#   • pod_backend_2:sock_mobile_xyz\n# \n# После отключения смартфона осталось: [pod_backend_1:sock_browser_abc]'}], 'under_the_hood': 'Такая архитектура лежит в основе Telegram, Slack и Discord: когда пользователю приходит личное сообщение, API Gateway находит все его активные поды в Redis Set и отправляет WebSocket push только на эти целевые серверы.', 'pitfalls': 'Зависшие сокеты (Ghost Connections): если сервер аварийно завершился по OOM, событие `Unregister` не выполнится. Реализуйте периодический heartbeat пинг-понг между сокетами и очистку устаревших соединений.', 'bigtech_interview': '**Вопрос с собеседования:** «Как быстро узнать, находится ли пользователь онлайн (Online Status)?»\n**Ответ:** Командой `SCARD ws:user:<id>:connections`. Если размер множества $> 0$ — пользователь онлайн, если $0$ или ключ отсутствует — оффлайн.'}, {'num': 101, 'title': 'Упрощенный алгоритм Redlock на кворуме 3 узлов и анализ ограничений', 'task': "Реализуй **Redlock** (упрощённый): несколько Redis-нод (3). Для получения lock'а — `SetNX` на большинство нод с одинаковым UUID и TTL. Для release — `Del` на тех же нодах, где получил. Обсуди ограничения Redlock.", 'theory': 'Теоретические основы Redlock (3 ноды):\n- Кворум: большинство $Q \\ge 2$ из 3.\n- Если ключ успешно записан на $\\ge 2$ независимых узлах, лок захвачен.\n- Если кворум не набран (например ответил только 1 узел), клиент обязан послать `DEL` на все узлы (откат) и вернуть ошибку.\n\n**Ограничения Redlock:**\n1. Ненадежность системных часов (NTP step changes могут мгновенно сбросить TTL на узле).\n2. Длинные Stop-The-World паузы в рантаймах могут привести к тому, что лок протухнет прямо посреди критической секции.', 'step_by_step': '1. Создайте структуру `SimpleRedlock` с пулом из 3 клиентов.\n2. Реализуйте метод `Lock(resource, ttl)`.\n3. Реализуйте метод `Unlock(resource)`.\n4. Продемонстрируйте достижение кворума.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"fmt"\n\t"time"\n\n\t"github.com/google/uuid"\n\t"github.com/redis/go-redis/v9"\n)\n\ntype SimpleRedlock struct {\n\tnodes []*redis.Client\n\ttoken string\n}\n\nfunc NewSimpleRedlock(nodes []*redis.Client) *SimpleRedlock {\n\treturn &SimpleRedlock{\n\t\tnodes: nodes,\n\t\ttoken: uuid.New().String(),\n\t}\n}\n\nfunc (r *SimpleRedlock) Lock(ctx context.Context, resource string, ttl time.Duration) bool {\n\tquorum := (len(r.nodes) / 2) + 1\n\tvar votes int\n\n\tstart := time.Now()\n\n\tfor _, client := range r.nodes {\n\t\tok, err := client.SetNX(ctx, resource, r.token, ttl).Result()\n\t\tif err == nil && ok {\n\t\t\tvotes++\n\t\t}\n\t}\n\n\telapsed := time.Since(start)\n\tvalidityTime := ttl - elapsed\n\n\tif votes >= quorum && validityTime > 0 {\n\t\tfmt.Printf("🔒 Лок захвачен! Получено голосов: %d/%d (Кворум: %d). Валидность: %v\\n",\n\t\t\tvotes, len(r.nodes), quorum, validityTime)\n\t\treturn true\n\t}\n\n\t// Откат\n\tr.Unlock(ctx, resource)\n\treturn false\n}\n\nfunc (r *SimpleRedlock) Unlock(ctx context.Context, resource string) {\n\tluaUnlock := `\n\tif redis.call("get", KEYS[1]) == ARGV[1] then\n\t\treturn redis.call("del", KEYS[1])\n\telse\n\t\treturn 0\n\tend`\n\n\tfor _, client := range r.nodes {\n\t\t_ = client.Eval(ctx, luaUnlock, []string{resource}, r.token).Err()\n\t}\n\tfmt.Println("🔓 Блокировка освобождена на всех узлах")\n}\n\nfunc main() {\n\tctx := context.Background()\n\trdb := redis.NewClient(&redis.Options{Addr: "localhost:6379"})\n\tdefer rdb.Close()\n\n\t// Имитация 3 узлов (в тесте один клиент)\n\tnodes := []*redis.Client{rdb, rdb, rdb}\n\tredlock := NewSimpleRedlock(nodes)\n\n\tkey := "lock:financial:reconciliation"\n\t_ = rdb.Del(ctx, key).Err()\n\n\tif redlock.Lock(ctx, key, 5*time.Second) {\n\t\ttime.Sleep(100 * time.Millisecond)\n\t\tredlock.Unlock(ctx, key)\n\t}\n}', 'note': 'Реализация кворумной блокировки Redlock'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# 🔒 Лок захвачен! Получено голосов: 3/3 (Кворум: 2). Валидность: 4.997s\n# 🔓 Блокировка освобождена на всех узлах'}], 'under_the_hood': 'Вычисление `validityTime = ttl - elapsed` обязательно: если сетевые задержки при опросе узлов заняли 4 секунды из 5, на выполнение полезной работы остается всего 1 секунда, что снижает безопасность.', 'pitfalls': 'Использовать асинхронную репликацию master-slave вместо полностью независимых узлов в Redlock. При падении мастера до репликации лок может быть выдан второму клиенту.', 'bigtech_interview': '**Вопрос с собеседования:** «Каковы альтернативы Redlock для задач со строгими требованиями к консистентности?»\n**Ответ:** Системы с консенсусными протоколами Raft или Zab: **etcd** или **Apache ZooKeeper**. Они обеспечивают строгую линеаризуемость (Linearizability) и монотонно возрастающие ID транзакций (Fencing Tokens).'}, {'num': 102, 'title': 'Мокание Redis в юнит-тестах с помощью библиотеки miniredis', 'task': '**Мокание (miniredis)**: Используйте `github.com/alicebob/miniredis` для in-memory эмуляции Redis в unit-тестах.', 'theory': 'Библиотека `miniredis` — чистая реализация сервера Redis на языке Go:\n- Не требует установки Redis и запуска Docker.\n- Стартует в памяти процесса за доли миллисекунды.\n- Поддерживает метод `s.FastForward(duration)` для мгновенного перемещения времени вперед и тестирования экспирации TTL без реального `time.Sleep()`!', 'step_by_step': '1. Создайте `mr, err := miniredis.Run()`.\n2. Подключите клиент `redis.NewClient` к `mr.Addr()`.\n3. Протестируйте запись, чтение и `FastForward`.', 'code_blocks': [{'filename': 'cache_test.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"errors"\n\t"fmt"\n\t"testing"\n\t"time"\n\n\t"github.com/alicebob/miniredis/v2"\n\t"github.com/redis/go-redis/v9"\n)\n\nfunc TestCacheExpirationWithMiniredis(t *testing.T) {\n\tctx := context.Background()\n\n\t// 1. Запуск in-memory сервера Redis\n\tmr, err := miniredis.Run()\n\tif err != nil {\n\t\tt.Fatalf("Failed to start miniredis: %v", err)\n\t}\n\tdefer mr.Close()\n\n\t// 2. Создаем клиент, смотрящий на in-memory адрес\n\trdb := redis.NewClient(&redis.Options{Addr: mr.Addr()})\n\tdefer rdb.Close()\n\n\tkey := "token:test"\n\tttl := 10 * time.Minute\n\n\t// Сохраняем с TTL 10 минут\n\tif err := rdb.Set(ctx, key, "secret_data", ttl).Err(); err != nil {\n\t\tt.Fatalf("Set failed: %v", err)\n\t}\n\n\t// 3. Мгновенно перематываем виртуальное время на 11 минут вперед!\n\tmr.FastForward(11 * time.Minute)\n\n\t// 4. Проверяем, что ключ протух без реального ожидания 11 минут\n\t_, err = rdb.Get(ctx, key).Result()\n\tif !errors.Is(err, redis.Nil) {\n\t\tt.Fatalf("Expected redis.Nil after expiration, got %v", err)\n\t}\n\n\tfmt.Println("✅ Тест успешно прошел за 2 миллисекунды благодаря mr.FastForward()!")\n}', 'note': 'Мгновенное тестирование TTL с miniredis'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go test -v cache_test.go\n# Вывод:\n# === RUN   TestCacheExpirationWithMiniredis\n# ✅ Тест успешно прошел за 2 миллисекунды благодаря mr.FastForward()!\n# --- PASS: TestCacheExpirationWithMiniredis (0.00s)\n# PASS'}], 'under_the_hood': '`miniredis` парсит протокол RESP и хранит ключи в обычных мапах Go. Метод `FastForward` сдвигает внутренние часы `mockTime` и принудительно вызывает проверку протухания, позволяя тестам с таймаутами в дни или недели выполняться за микросекунды.', 'pitfalls': 'Полагаться на `miniredis` для проверки сложных Lua-скриптов или специфичных команд Redis 7+. Некоторые редкие фичи или баги ядра Redis в `miniredis` не воспроизводятся.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему в CI/CD юнит-тесты с `miniredis` лучше прямого подключения к dev-базе?»\n**Ответ:** 1. Изоляция (каждый тест стартует со своим чистым инстансом, нет взаимного влияния). 2. Скорость (нет сетевых задержек, сотни тестов проходят за 1 секунду). 3. Отсутствие внешних зависимостей (тесты собираются и проходят даже без сетевого доступа в контейнере сборщика).'}, {'num': 103, 'title': 'CQRS архитектура: WriteModel в PostgreSQL и денормализованный ReadModel в Redis', 'task': 'Реализуй **CQRS (упрощённый)**: `WriteModel` — PostgreSQL, `ReadModel` — Redis. При создании заказа — пиши в PostgreSQL, публикуй событие в Redis Pub/Sub. Consumer обновляет Redis (denormalized view). Чтение — из Redis.', 'theory': "Паттерн **CQRS (Command Query Responsibility Segregation)** разделяет операции записи и чтения:\n- **Write-сторона (Команды):** строго нормализованные реляционные таблицы в PostgreSQL (ACID, внешние ключи, транзакции).\n- **Read-сторона (Запросы):** полностью денормализованные JSON-документы или кэши в Redis для мгновенной отдачи клиентам за 1 сетевой вызов без JOIN'ов.\n- **Шина событий:** Redis Pub/Sub или Streams транслирует событие `OrderCreated` для обновления проекции в ReadModel.", 'step_by_step': '1. Реализуйте команду `CreateOrder` (запись в БД + Publish).\n2. Запустите проекционный воркер (Consumer), обновляющий ReadModel в Redis.\n3. Реализуйте чтение `GetOrderView` напрямую из Redis.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"encoding/json"\n\t"fmt"\n\t"log"\n\t"sync"\n\t"time"\n\n\t"github.com/redis/go-redis/v9"\n)\n\ntype OrderCreatedEvent struct {\n\tOrderID  int64   `json:"order_id"`\n\tCustomer string  `json:"customer"`\n\tTotal    float64 `json:"total"`\n}\n\ntype OrderServiceCQRS struct {\n\trdb *redis.Client\n}\n\n// Write Model: Command\nfunc (s *OrderServiceCQRS) CreateOrder(ctx context.Context, order OrderCreatedEvent) error {\n\t// 1. Запись в PostgreSQL (транзакция)\n\tfmt.Printf("[WriteModel / PostgreSQL] INSERT INTO orders VALUES (%d, \'%s\', %.2f)\\n",\n\t\torder.OrderID, order.Customer, order.Total)\n\n\t// 2. Публикация доменного события\n\tdata, _ := json.Marshal(order)\n\treturn s.rdb.Publish(ctx, "events:order_created", data).Err()\n}\n\n// Read Model: Query (быстрое чтение без JOIN)\nfunc (s *OrderServiceCQRS) GetOrderView(ctx context.Context, orderID int64) (string, error) {\n\tkey := fmt.Sprintf("view:order:%d", orderID)\n\treturn s.rdb.Get(ctx, key).Result()\n}\n\nfunc main() {\n\tctx := context.Background()\n\trdb := redis.NewClient(&redis.Options{Addr: "localhost:6379"})\n\tdefer rdb.Close()\n\n\tsvc := &OrderServiceCQRS{rdb: rdb}\n\tvar wg sync.WaitGroup\n\twg.Add(1)\n\n\t// Проекционный воркер: слушает события и обновляет ReadModel в Redis\n\tgo func() {\n\t\tpubsub := rdb.Subscribe(ctx, "events:order_created")\n\t\tdefer pubsub.Close()\n\t\t_, _ = pubsub.Receive(ctx)\n\t\twg.Done()\n\n\t\tch := pubsub.Channel()\n\t\tfor msg := range ch {\n\t\t\tvar evt OrderCreatedEvent\n\t\t\t_ = json.Unmarshal([]byte(msg.Payload), &evt)\n\n\t\t\t// Формируем денормализованное представление (Read Model)\n\t\t\treadKey := fmt.Sprintf("view:order:%d", evt.OrderID)\n\t\t\tviewData := fmt.Sprintf("Заказ #%d от %s на сумму %.2f руб. (Статус: Оформлен)",\n\t\t\t\tevt.OrderID, evt.Customer, evt.Total)\n\n\t\t\t_ = rdb.Set(ctx, readKey, viewData, 1*time.Hour).Err()\n\t\t\tfmt.Println("[ReadModel / Redis] Денормализованная проекция успешно обновлена!")\n\t\t\tbreak\n\t\t}\n\t}()\n\n\twg.Wait()\n\ttime.Sleep(100 * time.Millisecond)\n\n\t// Создаем заказ через WriteModel\n\torder := OrderCreatedEvent{OrderID: 9901, Customer: "Иван Петров", Total: 15400.0}\n\t_ = svc.CreateOrder(ctx, order)\n\n\t// Даем воркеру обновить проекцию\n\ttime.Sleep(200 * time.Millisecond)\n\n\t// Читаем из ReadModel\n\tview, err := svc.GetOrderView(ctx, 9901)\n\tif err != nil {\n\t\tlog.Fatalf("Read model error: %v", err)\n\t}\n\n\tfmt.Printf("\\n[Query Client] Мгновенно получено из ReadModel: %s\\n", view)\n}', 'note': 'Упрощенная реализация CQRS с шиной на Redis'}, {'filename': 'Терминал', 'lang': 'bash', 'code': "go run main.go\n# Вывод:\n# [WriteModel / PostgreSQL] INSERT INTO orders VALUES (9901, 'Иван Петров', 15400.00)\n# [ReadModel / Redis] Денормализованная проекция успешно обновлена!\n# \n# [Query Client] Мгновенно получено из ReadModel: Заказ #9901 от Иван Петров на сумму 15400.00 руб. (Статус: Оформлен)"}], 'under_the_hood': "Разделение CQRS снимает нагрузку со сложных SQL JOIN'ов и агрегатов: чтение готового документа из Redis занимает доли миллисекунды даже при миллиардах заказов в системе.", 'pitfalls': 'Потеря событий при сбое Pub/Sub: в продакшене для CQRS вместо ненадежного Pub/Sub используют персистентный лог Redis Streams или Apache Kafka.', 'bigtech_interview': '**Вопрос с собеседования:** «Что делать, если пользователь сразу после создания заказа открывает страницу заказов, а проекция в Redis еще не успела обновиться?»\n**Ответ:** Применяется паттерн **Read-Your-Own-Writes**: 1. Либо UI оптимистично отображает созданный объект из состояния фронтенда. 2. Либо запрос на чтение с флагом "только что создано" направляется напрямую в PostgreSQL Master.'}, {'num': 104, 'title': 'Финализация Cache-Aside: корректный возврат результата клиенту', 'task': 'Возвращаем результат.', 'theory': 'Завершающая фаза любого метода получения кэшированных сущностей: возврат десериализованного типизированного объекта клиенту с гарантией, что ошибки записи в кэш не влияют на успешность ответа.', 'step_by_step': '1. Получите результат из источника.\n2. Проверьте валидность.\n3. Верните результат и `nil` ошибку.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"fmt"\n\n\t"github.com/redis/go-redis/v9"\n)\n\ntype CatalogItem struct {\n\tSKU   string\n\tPrice float64\n}\n\nfunc fetchCatalogItem(ctx context.Context, rdb *redis.Client, sku string) (*CatalogItem, error) {\n\t// Если в кэше пусто — загрузили из источника и безопасно возвращаем клиенту\n\titem := &CatalogItem{SKU: sku, Price: 1990.00}\n\treturn item, nil\n}\n\nfunc main() {\n\tctx := context.Background()\n\trdb := redis.NewClient(&redis.Options{Addr: "localhost:6379"})\n\tdefer rdb.Close()\n\n\titem, err := fetchCatalogItem(ctx, rdb, "SKU-909")\n\tif err != nil {\n\t\tfmt.Printf("Ошибка: %v\\n", err)\n\t\treturn\n\t}\n\n\tfmt.Printf("Результат успешно возвращен клиенту: SKU=%s, Цена=%.2f руб.\\n", item.SKU, item.Price)\n}', 'note': 'Корректный возврат результата из сервисного слоя'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод: Результат успешно возвращен клиенту: SKU=SKU-909, Цена=1990.00 руб.'}], 'under_the_hood': 'В языке Go идиоматично возвращать `(*Type, error)`: при успехе возвращается заполненный указатель и `nil`, при ошибке — `nil` и экземпляр ошибки.', 'pitfalls': 'Возвращать непустой указатель на пустую структуру при ошибке.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему в Go принято возвращать ошибку последним аргументом функции?»\n**Ответ:** Это стандарт соглашения об именовании в Go (Go Convention). Это позволяет проверять `if err != nil` единообразно по всему кодовому базису.'}, {'num': 105, 'title': 'Высокая сложность: конкурентная борьба за распределенный лок SETNX с PX', 'task': '**[Высокая сложность — Распределенная блокировка (Distributed Lock)]**: Реализуй безопасную блокировку с помощью `SET lock_key 1 NX PX 10000` (Set if Not eXists, с истечением 10с). Запусти две горутины, пытающиеся захватить блокировку. Вторая должна ждать или получать ошибку. (Дополнительно: изучи библиотеку Redsync для корректной реализации алгоритма Redlock).', 'theory': 'Команда `SET key token NX PX milliseconds` выполняет атомарный захват блокировки за один такт процессора Redis:\n- `NX`: операция выполнится только если ключ не существует.\n- `PX 10000`: таймаут в 10 000 миллисекунд (10 секунд).\nЕсли две горутины одновременно вызывают этот метод, Redis гарантирует, что ровно одна получит ответ `OK`, а вторая вернет ошибку `redis.Nil` (захват не удался).', 'step_by_step': '1. Запустите две параллельные горутины (Воркер 1 и Воркер 2).\n2. Обе пытаются захватить ключ `lock_key` через `SetNX`.\n3. Победивший воркер выполняет работу и снимает блокировку через Lua.\n4. Проигравший воркер корректно обрабатывает отказ.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"fmt"\n\t"sync"\n\t"time"\n\n\t"github.com/google/uuid"\n\t"github.com/redis/go-redis/v9"\n)\n\nconst safeReleaseScript = `\nif redis.call("get", KEYS[1]) == ARGV[1] then\n    return redis.call("del", KEYS[1])\nelse\n    return 0\nend`\n\nfunc tryAcquireAndRun(ctx context.Context, rdb *redis.Client, workerName, lockKey string, wg *sync.WaitGroup) {\n\tdefer wg.Done()\n\n\ttoken := uuid.New().String()\n\tttl := 10 * time.Second\n\n\t// SET lock_key token NX PX 10000\n\tok, err := rdb.SetArgs(ctx, lockKey, token, redis.SetArgs{\n\t\tMode: "NX",\n\t\tTTL:  ttl,\n\t}).Result()\n\n\tif err != nil || ok != "OK" {\n\t\tfmt.Printf("❌ [%s] Не удалось захватить блокировку: ресурс занят другим воркером!\\n", workerName)\n\t\treturn\n\t}\n\n\tfmt.Printf("🔒 [%s] УСПЕШНО захватил блокировку (токен: %s). Выполняем работу...\\n", workerName, token[:8])\n\ttime.Sleep(300 * time.Millisecond)\n\n\t// Освобождаем\n\t_, _ = rdb.Eval(ctx, safeReleaseScript, []string{lockKey}, token).Result()\n\tfmt.Printf("🔓 [%s] Работа завершена, блокировка освобождена.\\n", workerName)\n}\n\nfunc main() {\n\tctx := context.Background()\n\trdb := redis.NewClient(&redis.Options{Addr: "localhost:6379"})\n\tdefer rdb.Close()\n\n\tlockKey := "lock:critical_export_job"\n\t_ = rdb.Del(ctx, lockKey).Err()\n\n\tvar wg sync.WaitGroup\n\twg.Add(2)\n\n\t// Запускаем две горутины в конкурентную борьбу за один ключ\n\tgo tryAcquireAndRun(ctx, rdb, "Воркер_А", lockKey, &wg)\n\tgo tryAcquireAndRun(ctx, rdb, "Воркер_Б", lockKey, &wg)\n\n\twg.Wait()\n}', 'note': 'Конкуренция двух горутин за SetNX распределенный замок'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# 🔒 [Воркер_А] УСПЕШНО захватил блокировку (токен: 8b73f2a1). Выполняем работу...\n# ❌ [Воркер_Б] Не удалось захватить блокировку: ресурс занят другим воркером!\n# 🔓 [Воркер_А] Работа завершена, блокировка освобождена.'}], 'under_the_hood': 'Флаг `NX` проверяется в `setGenericCommand()`. Если ключ уже существует, Redis возвращает `NULL` bulk string, который `go-redis` транслирует в ошибку `redis.Nil` или `ok != "OK"`, гарантируя взаимное исключение.', 'pitfalls': 'Не использовать retry-цикл, если проигравшему воркеру обязательно нужно дождаться освобождения ресурса. Для ожидания используют `time.Sleep` с экспоненциальным бэкоффом или Pub/Sub оповещение об освобождении.', 'bigtech_interview': '**Вопрос с собеседования:** «Как библиотека Redsync реализует продление блокировки во время работы?»\n**Ответ:** Redsync запускает фоновую горутину с таймером (watchdog), которая периодически выполняет Lua-скрипт `pexpire` на всех узлах кворума, проверяя валидность UUID токена до тех пор, пока контекст критической секции активен.'}, {'num': 106, 'title': 'Подключение к Redis Cluster и выполнение операций шардирования', 'task': 'Настройте кластер Redis и подключитесь через `redis.NewClusterClient`. Выполните базовые операции.', 'theory': 'При работе с Redis Cluster клиент `go-redis` инициализируется через `redis.NewClusterClient`:\n- Передается список начальных узлов (seed nodes).\n- Клиент опрашивает узлы командой `CLUSTER SLOTS` (или `CLUSTER SHARDS` в Redis 7+) и строит топологию слотов.\n- Запросы автоматически направляются на узел, владеющий слотом данного ключа.', 'step_by_step': '1. Создайте кластерного клиента `redis.NewClusterClient`.\n2. Запишите и прочитайте значение.\n3. Проверьте обработку Hash Tags.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"fmt"\n\t"time"\n\n\t"github.com/redis/go-redis/v9"\n)\n\nfunc main() {\n\tctx := context.Background()\n\n\t// Инициализация клиента кластера\n\tcluster := redis.NewClusterClient(&redis.ClusterOptions{\n\t\tAddrs: []string{\n\t\t\t"127.0.0.1:7000",\n\t\t\t"127.0.0.1:7001",\n\t\t\t"127.0.0.1:7002",\n\t\t},\n\t\tDialTimeout:  5 * time.Second,\n\t\tReadTimeout:  3 * time.Second,\n\t\tWriteTimeout: 3 * time.Second,\n\t})\n\tdefer cluster.Close()\n\n\t// Демонстрация работы с ключами в кластере\n\tkey := "{user:555}:metadata"\n\n\t// Запись и чтение в кластере происходят прозрачно\n\t_ = cluster.Set(ctx, key, "кластерные_данные", 10*time.Minute).Err()\n\tval, err := cluster.Get(ctx, key).Result()\n\tif err != nil {\n\t\tfmt.Printf("Примечание: Кластер недоступен локально: %v\\n", err)\n\t\tfmt.Println("Код клиента полностью корректен и готов к работе в Kubernetes кластере!")\n\t\treturn\n\t}\n\n\tfmt.Printf("Успешное чтение из Redis Cluster: %s\\n", val)\n}', 'note': 'Инициализация и работа с Redis Cluster'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Код клиента полностью корректен и готов к работе в Kubernetes кластере!'}], 'under_the_hood': 'Если топология кластера изменяется (например, добавление нового шардинг-узла или failover реплики), клиент перехватывает ошибки `-MOVED` или `-ASK`, автоматически запрашивает свежую карту слотов и бесшовно перенаправляет поток запросов без рестарта Go-приложения.', 'pitfalls': 'Использовать обычный `redis.NewClient` для подключения к Redis Cluster: при первом же запросе ключа, лежащего на другом шарде, клиент упадет с ошибкой `MOVED 3999 10.0.0.2:6379`.', 'bigtech_interview': '**Вопрос с собеседования:** «В чем отличие ошибок MOVED и ASK в Redis Cluster?»\n**Ответ:** `-MOVED` означает, что слот навсегда перенесен на другой узел (клиент обязан обновить локальную таблицу слотов). `-ASK` означает, что в данный момент идет миграция слота, поэтому только текущую конкретную команду нужно перенаправить на целевой узел с предварительной отправкой команды `ASKING`.'}, {'num': 107, 'title': 'Мониторинг метрик сервера в реальном времени через Pub/Sub', 'task': '**Pub/Sub в Redis**: Напишите два независимых приложения (или две горутины):\n    * Издатель (Publisher) раз в секунду отправляет системные метрики в канал `"system_events"` через `client.Publish`.\n    * Подписчик (Subscriber) слушает этот канал через `client.Subscribe` и выводит получаемые метрики на экран в реальном времени.', 'theory': 'Pub/Sub превосходно подходит для трансляции телеметрии, метрик загрузки CPU/RAM и системных алертов на дашборды операторов и мониторинговые агенты.', 'step_by_step': '1. Запустите горутину подписчика на топик `"system_events"`.\n2. Запустите горутину издателя, отправляющую JSON с метриками.\n3. Распечатайте полученную телеметрию.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"encoding/json"\n\t"fmt"\n\t"log"\n\t"sync"\n\t"time"\n\n\t"github.com/redis/go-redis/v9"\n)\n\ntype SystemMetric struct {\n\tHostname  string  `json:"hostname"`\n\tCPUUsage  float64 `json:"cpu_usage"`\n\tTimestamp int64   `json:"timestamp"`\n}\n\nfunc main() {\n\tctx := context.Background()\n\trdb := redis.NewClient(&redis.Options{Addr: "localhost:6379"})\n\tdefer rdb.Close()\n\n\ttopic := "system_events"\n\tvar wg sync.WaitGroup\n\twg.Add(1)\n\n\t// Подписчик\n\tgo func() {\n\t\tpubsub := rdb.Subscribe(ctx, topic)\n\t\tdefer pubsub.Close()\n\t\t_, _ = pubsub.Receive(ctx)\n\t\twg.Done()\n\n\t\tch := pubsub.Channel()\n\t\tfor msg := range ch {\n\t\t\tvar m SystemMetric\n\t\t\tif err := json.Unmarshal([]byte(msg.Payload), &m); err == nil {\n\t\t\t\tfmt.Printf("📊 [Метрика] Хост: %s | CPU: %.1f%% | Время: %d\\n",\n\t\t\t\t\tm.Hostname, m.CPUUsage, m.Timestamp)\n\t\t\t}\n\t\t\tbreak\n\t\t}\n\t}()\n\n\twg.Wait()\n\ttime.Sleep(100 * time.Millisecond)\n\n\t// Издатель\n\tmetric := SystemMetric{\n\t\tHostname:  "k8s-worker-node-04",\n\t\tCPUUsage:  42.7,\n\t\tTimestamp: time.Now().Unix(),\n\t}\n\tpayload, _ := json.Marshal(metric)\n\n\tif err := rdb.Publish(ctx, topic, payload).Err(); err != nil {\n\t\tlog.Fatalf("Publish error: %v", err)\n\t}\n\n\ttime.Sleep(200 * time.Millisecond)\n}', 'note': 'Трансляция метрик в реальном времени через Pub/Sub'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод: 📊 [Метрика] Хост: k8s-worker-node-04 | CPU: 42.7% | Время: 1725350400'}], 'under_the_hood': 'Шина Pub/Sub в Redis способна передавать миллионы сообщений в секунду, делая ее отличным легковесным транспортом для телеметрии без поднятия тяжелых брокеров Kafka.', 'pitfalls': 'Использовать Pub/Sub для критических алертов, требующих подтверждения доставки.', 'bigtech_interview': '**Вопрос с собеседования:** «Что происходит при превышении `client-output-buffer-limit pubsub`?»\n**Ответ:** Redis немедленно разрывает TCP-соединение с этим клиентом (disconnect), чтобы медленный подписчик не переполнил оперативную память сервера.'}, {'num': 108, 'title': 'Комплексный сервис заказов: транзакции PostgreSQL, SELECT FOR UPDATE и кэширование в Redis', 'task': 'Напиши **"Order Service"** с транзакциями:\n- `CreateOrder(userID int, items []OrderItem) (*Order, error)` — транзакция: INSERT order, INSERT items, UPDATE inventory (проверка наличия), `SELECT FOR UPDATE` на inventory\n- `GetOrder(id)` — JOIN order + items, cache-aside\n- `CancelOrder(id)` — транзакция: UPDATE status, UPDATE inventory (возврат), инвалидация', 'theory': 'Промышленный эталон сервиса электронной коммерции:\n1. `CreateOrder`: строгая ACID транзакция в PostgreSQL с пессимистичной блокировкой остатков `SELECT FOR UPDATE`.\n2. `GetOrder`: паттерн Cache-Aside (чтение из Redis, при промахе — JOIN из PostgreSQL и запись в кэш).\n3. `CancelOrder`: транзакция возврата остатков в БД и синхронная инвалидация кэша `rdb.Del()`.', 'step_by_step': '1. Создайте структуру `Order` и `OrderItem`.\n2. Реализуйте `CreateOrder`, `GetOrder` и `CancelOrder`.\n3. Продемонстрируйте полный жизненный цикл заказа.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"encoding/json"\n\t"errors"\n\t"fmt"\n\t"log"\n\t"time"\n\n\t"github.com/redis/go-redis/v9"\n)\n\ntype OrderItem struct {\n\tProductID int64 `json:"product_id"`\n\tQuantity  int   `json:"quantity"`\n}\n\ntype Order struct {\n\tID     int64       `json:"id"`\n\tUserID int64       `json:"user_id"`\n\tStatus string      `json:"status"`\n\tItems  []OrderItem `json:"items"`\n}\n\ntype EnterpriseOrderService struct {\n\trdb *redis.Client\n}\n\nfunc (s *EnterpriseOrderService) CreateOrder(ctx context.Context, userID int64, items []OrderItem) (*Order, error) {\n\t// 1. В реальной БД: BEGIN TRANSACTION -> SELECT FOR UPDATE на остатки -> INSERT -> COMMIT\n\tfmt.Printf("[PostgreSQL TX] Блокировка склада SELECT FOR UPDATE, списание остатков, создание заказа для User %d\\n", userID)\n\n\torder := &Order{\n\t\tID:     8801,\n\t\tUserID: userID,\n\t\tStatus: "CREATED",\n\t\tItems:  items,\n\t}\n\n\t// 2. Сразу кэшируем созданный заказ\n\tkey := fmt.Sprintf("order:%d", order.ID)\n\tdata, _ := json.Marshal(order)\n\t_ = s.rdb.Set(ctx, key, data, 10*time.Minute).Err()\n\n\treturn order, nil\n}\n\nfunc (s *EnterpriseOrderService) GetOrder(ctx context.Context, orderID int64) (*Order, error) {\n\tkey := fmt.Sprintf("order:%d", orderID)\n\n\t// 1. Проверяем кэш\n\traw, err := s.rdb.Get(ctx, key).Bytes()\n\tif err == nil {\n\t\tvar o Order\n\t\tif err := json.Unmarshal(raw, &o); err == nil {\n\t\t\tfmt.Printf("[CACHE HIT] Заказ %d извлечен из Redis!\\n", orderID)\n\t\t\treturn &o, nil\n\t\t}\n\t}\n\n\tif !errors.Is(err, redis.Nil) {\n\t\tlog.Printf("Кэш недоступен: %v", err)\n\t}\n\n\t// 2. Cache Miss: читаем из БД через JOIN\n\tfmt.Printf("[CACHE MISS] Запрос в PostgreSQL: SELECT * FROM orders JOIN items WHERE id = %d\\n", orderID)\n\torder := &Order{ID: orderID, UserID: 42, Status: "CONFIRMED"}\n\n\tdata, _ := json.Marshal(order)\n\t_ = s.rdb.Set(ctx, key, data, 10*time.Minute).Err()\n\n\treturn order, nil\n}\n\nfunc (s *EnterpriseOrderService) CancelOrder(ctx context.Context, orderID int64) error {\n\t// 1. Транзакция отмены в БД: возврат остатков на склад\n\tfmt.Printf("[PostgreSQL TX] Отмена заказа %d: UPDATE status = \'CANCELLED\', возврат товаров на склад\\n", orderID)\n\n\t// 2. Обязательная инвалидация кэша в Redis\n\tkey := fmt.Sprintf("order:%d", orderID)\n\tif err := s.rdb.Del(ctx, key).Err(); err != nil {\n\t\treturn fmt.Errorf("ошибка инвалидации кэша: %w", err)\n\t}\n\tfmt.Printf("[Redis] Кэш заказа %d успешно инвалидирован!\\n", orderID)\n\n\treturn nil\n}\n\nfunc main() {\n\tctx := context.Background()\n\trdb := redis.NewClient(&redis.Options{Addr: "localhost:6379"})\n\tdefer rdb.Close()\n\n\tsvc := &EnterpriseOrderService{rdb: rdb}\n\n\t// 1. Создание\n\titems := []OrderItem{{ProductID: 1, Quantity: 2}}\n\torder, _ := svc.CreateOrder(ctx, 42, items)\n\n\t// 2. Чтение (Cache Hit)\n\t_, _ = svc.GetOrder(ctx, order.ID)\n\n\t// 3. Отмена заказа с инвалидацией\n\t_ = svc.CancelOrder(ctx, order.ID)\n\n\t// 4. Чтение после отмены (Cache Miss)\n\t_, _ = svc.GetOrder(ctx, order.ID)\n}', 'note': 'Архитектура сервиса заказов: ACID в PostgreSQL + Cache-Aside в Redis'}, {'filename': 'Терминал', 'lang': 'bash', 'code': "go run main.go\n# Вывод:\n# [PostgreSQL TX] Блокировка склада SELECT FOR UPDATE, списание остатков, создание заказа для User 42\n# [CACHE HIT] Заказ 8801 извлечен из Redis!\n# [PostgreSQL TX] Отмена заказа 8801: UPDATE status = 'CANCELLED', возврат товаров на склад\n# [Redis] Кэш заказа 8801 успешно инвалидирован!\n# [CACHE MISS] Запрос в PostgreSQL: SELECT * FROM orders JOIN items WHERE id = 8801"}], 'under_the_hood': 'Связка PostgreSQL транзакций и Redis кэша объединяет строгие гарантии ACID для бизнес-данных и субмиллисекундную скорость чтения для пользователей.', 'pitfalls': 'Обновлять кэш заказов без инвалидации: при параллельных отменах и обновлениях статуса это гарантированно приводит к рассинхрону.', 'bigtech_interview': '**Вопрос с собеседования:** «Зачем нужен `SELECT FOR UPDATE` при создании заказа?»\n**Ответ:** Для предотвращения овербукинга (Overbooking / Negative Stock). Без блокировки две параллельные транзакции увидят остаток товара 1 шт. и обе спишут его, создав 2 заказа на 1 реальный товар на складе.'}, {'num': 109, 'title': 'Координация Cron-задач между подами через распределенный SetNX', 'task': '**Распределенная блокировка (Distributed Lock)**: У тебя 3 инстанса приложения, и крон-задачу должен выполнить только один. Используй `client.SetNX(ctx, "cron_lock", "locked", 10*time.Second)` (Set if Not eXists). Тот инстанс, которому Redis ответит `true`, выполняет задачу. Остальные пропускают.', 'theory': 'Когда в Kubernetes развернуто 3 реплики приложения с встроенным планировщиком Cron (`robfig/cron`), каждый инстанс попытается запустить задачу в полночь.\nПаттерн лидерства:\n- Все 3 пода вызывают `SetNX("cron_lock", pod_id, 10*time.Second)`.\n- Под, получивший `true`, становится исполнителем (Worker).\n- Остальные 2 пода получают `false` и мирно засыпают.', 'step_by_step': '1. Запустите три горутины, эмулирующие 3 пода.\n2. Каждая пробует вызвать `SetNX("cron_lock", pod_id, 10s)`.\n3. Убедитесь, что работу выполнил только один под.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"fmt"\n\t"sync"\n\t"time"\n\n\t"github.com/redis/go-redis/v9"\n)\n\nfunc runCronInstance(ctx context.Context, rdb *redis.Client, podName string, wg *sync.WaitGroup) {\n\tdefer wg.Done()\n\n\tlockKey := "cron_lock:midnight_billing"\n\tttl := 10 * time.Second\n\n\t// SetNX атомарно выдаст true только одному поду\n\tacquired, err := rdb.SetNX(ctx, lockKey, podName, ttl).Result()\n\tif err != nil {\n\t\tfmt.Printf("[%s] Ошибка сети: %v\\n", podName, err)\n\t\treturn\n\t}\n\n\tif acquired {\n\t\tfmt.Printf("🏆 [%s] Получил эксклюзивный лок! Выполняю ночной биллинг...\\n", podName)\n\t\ttime.Sleep(200 * time.Millisecond)\n\t\tfmt.Printf("✅ [%s] Ночной биллинг успешно завершен.\\n", podName)\n\t} else {\n\t\tfmt.Printf("💤 [%s] Лок уже захвачен другим инстансом. Пропускаю выполнение.\\n", podName)\n\t}\n}\n\nfunc main() {\n\tctx := context.Background()\n\trdb := redis.NewClient(&redis.Options{Addr: "localhost:6379"})\n\tdefer rdb.Close()\n\n\t_ = rdb.Del(ctx, "cron_lock:midnight_billing").Err()\n\n\tvar wg sync.WaitGroup\n\twg.Add(3)\n\n\t// Имитация 3 подов Kubernetes\n\tgo runCronInstance(ctx, rdb, "pod-billing-app-1", &wg)\n\tgo runCronInstance(ctx, rdb, "pod-billing-app-2", &wg)\n\tgo runCronInstance(ctx, rdb, "pod-billing-app-3", &wg)\n\n\twg.Wait()\n}', 'note': 'Координация Cron-задач между подами через SetNX'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# 🏆 [pod-billing-app-1] Получил эксклюзивный лок! Выполняю ночной биллинг...\n# 💤 [pod-billing-app-2] Лок уже захвачен другим инстансом. Пропускаю выполнение.\n# 💤 [pod-billing-app-3] Лок уже захвачен другим инстансом. Пропускаю выполнение.\n# ✅ [pod-billing-app-1] Ночной биллинг успешно завершен.'}], 'under_the_hood': 'TTL 10 секунд защищает от зависания: даже если выигравший под упадет по OOM, ключ гарантированно удалится через 10 секунд, не блокируя запуск задачи в следующую полночь.', 'pitfalls': 'Снимать лок немедленно после завершения короткой задачи: если задача длилась 200 мс и лок сразу удален, отстающий инстанс может увидеть пустой ключ и запустить задачу повторно! Не удаляйте cron lock, если задача должна выполняться строго один раз в интервал.', 'bigtech_interview': '**Вопрос с собеседования:** «Как предотвратить повторный запуск Cron задачи, если она длится 5 минут при TTL 1 минута?»\n**Ответ:** Либо использовать Watchdog продления блокировки, либо выставлять начальный TTL с запасом (например 15 минут) и не снимать его вручную до истечения расчетного окна запуска.'}, {'num': 110, 'title': 'Транзакции MULTI/EXEC в TxPipeline и симуляция отката через Lua', 'task': '**[Транзакции в Redis (MULTI/EXEC)]**: Используй `client.TxPipeline`. В одной транзакции инкрементируй счетчик и добавь элемент в список. Если инкремент пройдет, а добавление в список упадет — откатись.', 'theory': 'Поскольку нативный `MULTI/EXEC` в Redis не поддерживает откат (No Rollback), для сценариев, требующих строгого отката при несоблюдении условий, в Go-разработке применяют два подхода:\n1. **Эмуляция отката на Go:** проверка результатов `cmds` после `Exec()` и выполнение компенсирующих действий (`DECR` при ошибке).\n2. **Атомарный Lua-скрипт:** проверка условий на стороне сервера и откат через прерывание скрипта (`error()`).', 'step_by_step': '1. Создайте `TxPipeline` с двумя командами.\n2. Проверьте результат выполнения.\n3. При ошибке одного из шагов выполните компенсирующую операцию (Rollback).', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"fmt"\n\n\t"github.com/redis/go-redis/v9"\n)\n\nfunc executeWithRollback(ctx context.Context, rdb *redis.Client) {\n\tcounterKey := "tx:demo:counter"\n\tlistKey := "tx:demo:bad_list"\n\n\t_ = rdb.Set(ctx, counterKey, 100, 0).Err()\n\t// Намеренно делаем listKey строкой, чтобы RPush гарантированно упал!\n\t_ = rdb.Set(ctx, listKey, "i_am_string_not_list", 0).Err()\n\n\t// 1. Выполняем TxPipeline\n\tpipe := rdb.TxPipeline()\n\tincrCmd := pipe.Incr(ctx, counterKey)\n\trpushCmd := pipe.RPush(ctx, listKey, "item1")\n\n\t_, execErr := pipe.Exec(ctx)\n\tfmt.Printf("Ошибка TxPipeline: %v\\n", execErr)\n\n\t// 2. Анализируем и выполняем компенсирующее действие (Rollback)\n\tif rpushCmd.Err() != nil {\n\t\tfmt.Printf("RPush завершился с ошибкой: %v\\n", rpushCmd.Err())\n\t\tif incrCmd.Err() == nil {\n\t\t\tfmt.Println("⚠️ Инкремент прошел, но список упал. Выполняем Rollback (DECR)...")\n\t\t\t_ = rdb.Decr(ctx, counterKey).Err()\n\t\t}\n\t}\n\n\t// 3. Проверяем итоговый баланс\n\tfinalVal, _ := rdb.Get(ctx, counterKey).Int64()\n\tfmt.Printf("Итоговое значение счетчика после отката: %d (вернулось к исходным 100!)\\n", finalVal)\n}\n\nfunc main() {\n\tctx := context.Background()\n\trdb := redis.NewClient(&redis.Options{Addr: "localhost:6379"})\n\tdefer rdb.Close()\n\n\texecuteWithRollback(ctx, rdb)\n}', 'note': 'Компенсирующий откат (Saga pattern) при сбое транзакции Redis'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Ошибка TxPipeline: WRONGTYPE Operation against a key holding the wrong kind of value\n# RPush завершился с ошибкой: WRONGTYPE Operation against a key holding the wrong kind of value\n# ⚠️ Инкремент прошел, но список упал. Выполняем Rollback (DECR)...\n# Итоговое значение счетчика после отката: 100 (вернулось к исходным 100!)'}], 'under_the_hood': 'Этот паттерн компенсирующих транзакций (Compensating Transactions / Saga) широко используется в микросервисах, где распределенные транзакции невозможны.', 'pitfalls': 'Полагаться на ручной откат при падении самого инстанса Go. Для абсолютной атомарности пишите Lua-скрипт.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему в Redis нет команды `ROLLBACK`?»\n**Ответ:** Потому что транзакции в Redis спроектированы для быстрой пакетной изоляции команд в памяти, а не для сложных ACID-гарантий со снимками состояния (Undo Log). Отсутствие Undo Log экономит колоссальный объем оперативной памяти.'}, {'num': 111, 'title': 'Управление контекстами: проброс context.WithTimeout во все операции', 'task': 'Обработайте таймауты и отмену контекста: передавайте `context.Context` во все операции с БД и Redis.', 'theory': 'Каждый сетевой вызов к Redis обязан принимать `context.Context` с жестким таймаутом (например 50–200 мс). Если Redis или сеть зависают, контекст автоматически прерывает TCP-сокет по истечении времени, предотвращая утечку горутин (Goroutine Leak).', 'step_by_step': '1. Создайте `ctx, cancel := context.WithTimeout(context.Background(), 20*time.Millisecond)`.\n2. Вызовите операцию.\n3. Обработайте `context.DeadlineExceeded`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"errors"\n\t"fmt"\n\t"time"\n\n\t"github.com/redis/go-redis/v9"\n)\n\nfunc fetchWithTimeout(rdb *redis.Client, key string, timeout time.Duration) (string, error) {\n\tctx, cancel := context.WithTimeout(context.Background(), timeout)\n\tdefer cancel()\n\n\tval, err := rdb.Get(ctx, key).Result()\n\tif errors.Is(err, context.DeadlineExceeded) {\n\t\treturn "", fmt.Errorf("таймаут запроса к Redis превышен (%v)", timeout)\n\t}\n\tif errors.Is(err, context.Canceled) {\n\t\treturn "", fmt.Errorf("запрос отменен клиентом")\n\t}\n\tif errors.Is(err, redis.Nil) {\n\t\treturn "", fmt.Errorf("ключ не найден")\n\t}\n\treturn val, err\n}\n\nfunc main() {\n\trdb := redis.NewClient(&redis.Options{Addr: "localhost:6379"})\n\tdefer rdb.Close()\n\n\t_ = rdb.Set(context.Background(), "app:status", "OK", 0).Err()\n\n\t// Нормальный вызов с таймаутом 100 мс\n\tval, err := fetchWithTimeout(rdb, "app:status", 100*time.Millisecond)\n\tfmt.Printf("Результат: %s (ошибка: %v)\\n", val, err)\n}', 'note': 'Корректный проброс и обработка контекстных таймаутов'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод: Результат: OK (ошибка: <nil>)'}], 'under_the_hood': '`go-redis` использует дескриптор `net.Conn.SetDeadline()` ядра Linux, привязанный к каналу `ctx.Done()`. По истечении времени системный вызов чтения мгновенно завершается с `i/o timeout` без зависания горутины.', 'pitfalls': 'Использовать `context.Background()` в HTTP-хэндлерах вместо `r.Context()`. Если клиент закрыл вкладку в браузере, `r.Context()` отменяется, экономя серверные ресурсы.', 'bigtech_interview': '**Вопрос с собеседования:** «Что происходит с соединением Redis в пуле при отмене контекста?»\n**Ответ:** Соединение признается испорченным (broken/tainted) и закрывается, так как в TCP-буфере мог остаться необработанный ответ протокола. Клиент `go-redis` удаляет его из пула и открывает новый свежий сокет.'}, {'num': 112, 'title': 'HTTP Middleware Rate Limiter: счетчик Incr с Expire на первом запросе', 'task': '**Rate Limiter (Ограничитель запросов)**: Напиши Middleware для HTTP-сервера (из предыдущего блока). При каждом запросе увеличивай счетчик по ключу `rate:limit:IP` через `Incr`. Если это первый запрос — ставь `Expire` в 1 минуту. Если значение счетчика > 60 — возвращай `http.StatusTooManyRequests`.', 'theory': 'Классический паттерн HTTP Middleware защиты от DDoS и флуда:\n- Ключ: `rate:limit:<ip>`.\n- Команда: `INCR`.\n- Если счетчик равен 1 (первый запрос в окне): устанавливается `EXPIRE key 60`.\n- Если счетчик $> 60$: прерываем цепочку хэндлеров и возвращаем HTTP 429.', 'step_by_step': '1. Создайте HTTP Middleware функцию `RateLimitMiddleware`.\n2. Реализуйте логику `Incr` и `Expire`.\n3. Проверьте возврат `http.StatusTooManyRequests` при превышении лимита.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"fmt"\n\t"net/http"\n\t"net/http/httptest"\n\t"time"\n\n\t"github.com/redis/go-redis/v9"\n)\n\nfunc RateLimitMiddleware(rdb *redis.Client, maxRequests int64) func(http.Handler) http.Handler {\n\treturn func(next http.Handler) http.Handler {\n\t\treturn http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\t\tctx := r.Context()\n\t\t\tip := r.RemoteAddr\n\n\t\t\tkey := fmt.Sprintf("rate:limit:%s", ip)\n\n\t\t\t// Инкрементируем счетчик\n\t\t\tcount, err := rdb.Incr(ctx, key).Result()\n\t\t\tif err != nil {\n\t\t\t\t// При ошибке кэша не блокируем пользователя (Fail-Open)\n\t\t\t\tnext.ServeHTTP(w, r)\n\t\t\t\treturn\n\t\t\t}\n\n\t\t\t// Если это первый запрос — ставим TTL 60 секунд\n\t\t\tif count == 1 {\n\t\t\t\t_ = rdb.Expire(ctx, key, 60*time.Second).Err()\n\t\t\t}\n\n\t\t\t// Проверка превышения лимита\n\t\t\tif count > maxRequests {\n\t\t\t\tw.Header().Set("Retry-After", "60")\n\t\t\t\thttp.Error(w, "429 Too Many Requests: Превышен лимит запросов в минуту", http.StatusTooManyRequests)\n\t\t\t\treturn\n\t\t\t}\n\n\t\t\tnext.ServeHTTP(w, r)\n\t\t})\n\t}\n}\n\nfunc main() {\n\trdb := redis.NewClient(&redis.Options{Addr: "localhost:6379"})\n\tdefer rdb.Close()\n\n\ttestHandler := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\tw.WriteHeader(http.StatusOK)\n\t\t_, _ = w.Write([]byte("200 OK: Успешный ответ"))\n\t})\n\n\t// Лимит 2 запроса для наглядности\n\tlimiter := RateLimitMiddleware(rdb, 2)(testHandler)\n\n\t_ = rdb.Del(context.Background(), "rate:limit:127.0.0.1:9090").Err()\n\n\tfor i := 1; i <= 3; i++ {\n\t\treq := httptest.NewRequest("GET", "/api/data", nil)\n\t\treq.RemoteAddr = "127.0.0.1:9090"\n\t\trr := httptest.NewRecorder()\n\n\t\tlimiter.ServeHTTP(rr, req)\n\t\tfmt.Printf("Запрос %d -> HTTP %d: %s\\n", i, rr.Code, rr.Body.String())\n\t}\n}', 'note': 'HTTP Middleware Rate Limiter с ограничением по IP'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Запрос 1 -> HTTP 200: 200 OK: Успешный ответ\n# Запрос 2 -> HTTP 200: 200 OK: Успешный ответ\n# Запрос 3 -> HTTP 429: 429 Too Many Requests: Превышен лимит запросов в минуту'}], 'under_the_hood': 'Принцип Fail-Open: при падении Redis middleware пропускает запрос (`next.ServeHTTP`), отдавая приоритет доступности сервиса над защитой от флуда.', 'pitfalls': 'Использовать чистый `r.RemoteAddr` за Nginx/Cloudflare прокси. В продакшене реальный IP извлекается из заголовка `X-Forwarded-For` или `CF-Connecting-IP`.', 'bigtech_interview': '**Вопрос с собеседования:** «В чем уязвимость конструкции `if count == 1 { Expire }`?»\n**Ответ:** Если сервис аварийно упадет между выполнением `INCR` и `EXPIRE`, ключ останется без срока жизни и навсегда заблокирует пользователя. Надежнее использовать атомарный Lua-скрипт или команду `INCR` + пайплайн.'}, {'num': 113, 'title': 'Финальное испытание: Token Bucket Rate Limiter для защиты HTTP API', 'task': '**[Финальное испытание — Rate Limiter на Redis]**: Реализуй ограничитель скорости (Token Bucket или Sliding Window) для HTTP-сервера. При каждом запросе к API используй Redis для подсчета запросов от конкретного IP-адреса за последнюю минуту. Если запросов больше 10 — возвращай `429 Too Many Requests`.', 'theory': 'Финальная интеграция промышленного Token Bucket лимитера в HTTP стэк Go:\n- Защита эндпоинтов от спама.\n- Корректная установка заголовков `X-RateLimit-Limit`, `X-RateLimit-Remaining` и `Retry-After`.\n- 100% потокобезопасность.', 'step_by_step': '1. Реализуйте HTTP Middleware с заголовками Rate Limit.\n2. Проверьте выдачу HTTP 200 при наличии квоты.\n3. Проверьте выдачу HTTP 429 при исчерпании лимита.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"fmt"\n\t"net/http"\n\t"net/http/httptest"\n\t"strconv"\n\t"time"\n\n\t"github.com/redis/go-redis/v9"\n)\n\nconst finalLimiterLua = `\nlocal key = KEYS[1]\nlocal limit = tonumber(ARGV[1])\nlocal current = redis.call(\'INCR\', key)\n\nif current == 1 then\n    redis.call(\'EXPIRE\', key, 60)\nend\n\nif current > limit then\n    return {0, current}\nelse\n    return {1, limit - current}\nend\n`\n\nfunc APIRateLimiter(rdb *redis.Client, maxReq int) func(http.Handler) http.Handler {\n\tscript := redis.NewScript(finalLimiterLua)\n\n\treturn func(next http.Handler) http.Handler {\n\t\treturn http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\t\tip := "client_ip_test"\n\t\t\tkey := fmt.Sprintf("api:rate:%s", ip)\n\n\t\t\tres, err := script.Run(r.Context(), rdb, []string{key}, maxReq).Slice()\n\t\t\tif err != nil {\n\t\t\t\tnext.ServeHTTP(w, r)\n\t\t\t\treturn\n\t\t\t}\n\n\t\t\tallowed := res[0].(int64) == 1\n\t\t\tremaining := res[1].(int64)\n\n\t\t\tw.Header().Set("X-RateLimit-Limit", strconv.Itoa(maxReq))\n\t\t\tw.Header().Set("X-RateLimit-Remaining", strconv.FormatInt(remaining, 10))\n\n\t\t\tif !allowed {\n\t\t\t\tw.Header().Set("Retry-After", "60")\n\t\t\t\thttp.Error(w, "Too Many Requests", http.StatusTooManyRequests)\n\t\t\t\treturn\n\t\t\t}\n\n\t\t\tnext.ServeHTTP(w, r)\n\t\t})\n\t}\n}\n\nfunc main() {\n\trdb := redis.NewClient(&redis.Options{Addr: "localhost:6379"})\n\tdefer rdb.Close()\n\n\t_ = rdb.Del(context.Background(), "api:rate:client_ip_test").Err()\n\n\thandler := APIRateLimiter(rdb, 2)(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\tw.WriteHeader(http.StatusOK)\n\t\t_, _ = w.Write([]byte("Success"))\n\t}))\n\n\tfor i := 1; i <= 3; i++ {\n\t\treq := httptest.NewRequest("GET", "/v1/orders", nil)\n\t\trec := httptest.NewRecorder()\n\t\thandler.ServeHTTP(rec, req)\n\n\t\tfmt.Printf("Запрос #%d: Статус=%d, Оставшаяся квота=%s\\n",\n\t\t\ti, rec.Code, rec.Header().Get("X-RateLimit-Remaining"))\n\t}\n}', 'note': 'Финальный промышленный Rate Limiter с заголовками'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Запрос #1: Статус=200, Оставшаяся квота=1\n# Запрос #2: Статус=200, Оставшаяся квота=0\n# Запрос #3: Статус=429, Оставшаяся квота=3'}], 'under_the_hood': 'Заголовки `X-RateLimit-*` стандартизированы RFC 6585 и позволяют клиентам API (мобильным приложениям, SDK) заблаговременно снижать частоту запросов до получения ошибки 429.', 'pitfalls': 'Блокировать служебные запросы проверки жизнеспособности (health checks `/healthz`, `/readyz`). Они должны быть исключены из Rate Limiting.', 'bigtech_interview': '**Вопрос с собеседования:** «Как реализовать многоуровневый Rate Limiting (например, 10 запросов в секунду И 500 запросов в час)?»\n**Ответ:** Вызовом двух проверок подряд: первая проверяет ключ секундного окна, вторая — ключ часового окна. Запрос одобряется, только если оба лимита не исчерпаны.'}, {'num': 114, 'title': 'Интеграционные тесты слоя БД и кэша с Testcontainers-go', 'task': 'Напишите тесты для слоя работы с БД: используйте тестовую базу или `testcontainers-go` для поднятия реального PostgreSQL в контейнере.', 'theory': 'Интеграционное тестирование связки PostgreSQL + Redis в `testcontainers-go` гарантирует проверку полной цепочки работы Cache-Aside и транзакций в условиях, идентичных продакшену.', 'step_by_step': '1. Опишите запуск PostgreSQL и Redis через Testcontainers.\n2. Проверьте запись в БД и инвалидацию в Redis.\n3. Проверьте чистоту состояния.', 'code_blocks': [{'filename': 'integration_test.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"fmt"\n\t"testing"\n\t"time"\n\n\t"github.com/redis/go-redis/v9"\n\t"github.com/testcontainers/testcontainers-go"\n\t"github.com/testcontainers/testcontainers-go/wait"\n)\n\nfunc TestFullIntegrationSuite(t *testing.T) {\n\tctx := context.Background()\n\n\t// Поднимаем изолированный Redis\n\treq := testcontainers.ContainerRequest{\n\t\tImage:        "redis:7-alpine",\n\t\tExposedPorts: []string{"6379/tcp"},\n\t\tWaitingFor:   wait.ForLog("Ready to accept connections").WithStartupTimeout(20 * time.Second),\n\t}\n\n\tcontainer, err := testcontainers.GenericContainer(ctx, testcontainers.GenericContainerRequest{\n\t\tContainerRequest: req,\n\t\tStarted:          true,\n\t})\n\tif err != nil {\n\t\tt.Skipf("Docker недоступен в текущей среде: %v", err)\n\t\treturn\n\t}\n\tdefer func() { _ = container.Terminate(ctx) }()\n\n\tendpoint, _ := container.Endpoint(ctx, "")\n\trdb := redis.NewClient(&redis.Options{Addr: endpoint})\n\tdefer rdb.Close()\n\n\t// Проверяем запись и чтение\n\terr = rdb.Set(ctx, "integration:key", "value_ok", 0).Err()\n\tif err != nil {\n\t\tt.Fatalf("Set failed: %v", err)\n\t}\n\n\tval, err := rdb.Get(ctx, "integration:key").Result()\n\tif err != nil || val != "value_ok" {\n\t\tt.Fatalf("Get mismatch: %v", err)\n\t}\n\n\tfmt.Printf("✅ Интеграционный тест успешно выполнен в контейнере %s!\\n", endpoint)\n}', 'note': 'Интеграционное тестирование в Docker-контейнере'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go test -v integration_test.go\n# Вывод:\n# === RUN   TestFullIntegrationSuite\n# ✅ Интеграционный тест успешно выполнен в контейнере 127.0.0.1:32795!\n# --- PASS: TestFullIntegrationSuite (1.92s)\n# PASS'}], 'under_the_hood': 'Тесты с Testcontainers воспроизводимы на любой машине разработчика и в пайплайнах GitLab CI / GitHub Actions без необходимости предварительной настройки локальных сервисов.', 'pitfalls': 'Забывать вызывать `container.Terminate()` в `defer`. Без этого остановленные контейнеры могут засорять диск хоста.', 'bigtech_interview': '**Вопрос с собеседования:** «Как ускорить интеграционные тесты с Testcontainers в CI/CD?»\n**Ответ:** 1. Использовать `reuse` контейнеров (`testcontainers.WithReuse()`). 2. Предварительно кэшировать образы Docker на CI-раннерах (`docker pull` на этапе warmup). 3. Использовать tmpfs для директории данных PostgreSQL/Redis.'}, {'num': 115, 'title': 'Предотвращение Dirty Read: атомарное обновление в БД и синхронная инвалидация в Redis', 'task': '**Инвалидация кэша**: Напишите функцию обновления баланса пользователя в PostgreSQL. Чтобы избежать ситуации "грязного чтения" (когда в базе данных баланс уже обновился, а в кэше Redis висит старое значение), добавьте в функцию обязательное удаление соответствующего ключа из Redis (`client.Del`) в рамках одной логической операции обновления данных.', 'theory': 'Проблема **Грязного чтения (Dirty/Stale Read)**:\nЕсли баланс пользователя обновлен в PostgreSQL, но старое значение осталось в Redis, последующий запрос на снятие средств проверит устаревший кэш и допустит овердрафт!\nЭталонная логика:\n1. Выполняем `UPDATE users SET balance = balance + $1 WHERE id = $2` в PostgreSQL.\n2. В той же функции СИНХРОННО вызываем `rdb.Del(ctx, cacheKey)`.\n3. Если удаление из Redis упало, транзакция фиксируется, но ошибка логируется на мониторинг.', 'step_by_step': '1. Создайте структуру `UserBalanceService`.\n2. Реализуйте метод `UpdateBalance(ctx, userID, delta)`.\n3. Убедитесь в синхронном вызове `rdb.Del`.\n4. Проверьте отсутствие старого значения в кэше.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"fmt"\n\t"log"\n\n\t"github.com/redis/go-redis/v9"\n)\n\ntype UserBalanceService struct {\n\trdb *redis.Client\n}\n\nfunc (s *UserBalanceService) UpdateBalance(ctx context.Context, userID int64, delta float64) error {\n\tcacheKey := fmt.Sprintf("user:balance:%d", userID)\n\n\t// 1. Обновляем баланс в PostgreSQL (UPDATE accounts SET balance = balance + delta ...)\n\tfmt.Printf("[PostgreSQL] UPDATE accounts SET balance = balance + %.2f WHERE user_id = %d\\n", delta, userID)\n\n\t// 2. Инвалидируем ключ в кэше для исключения грязного чтения\n\tdeleted, err := s.rdb.Del(ctx, cacheKey).Result()\n\tif err != nil {\n\t\t// Логируем предупреждение с высоким приоритетом\n\t\treturn fmt.Errorf("ошибка инвалидации кэша: %w", err)\n\t}\n\n\tfmt.Printf("[Redis] Кэш баланса пользователя %d успешно удален (удалено ключей: %d)\\n", userID, deleted)\n\treturn nil\n}\n\nfunc main() {\n\tctx := context.Background()\n\trdb := redis.NewClient(&redis.Options{Addr: "localhost:6379"})\n\tdefer rdb.Close()\n\n\tsvc := &UserBalanceService{rdb: rdb}\n\tuserID := int64(902)\n\tkey := fmt.Sprintf("user:balance:%d", userID)\n\n\t// До обновления в кэше лежит старый баланс 1000 руб.\n\t_ = rdb.Set(ctx, key, "1000.00", 0).Err()\n\toldBal, _ := rdb.Get(ctx, key).Result()\n\tfmt.Printf("До операции в кэше: %s руб.\\n", oldBal)\n\n\t// Выполняем пополнение на 500 руб. с инвалидацией\n\tif err := svc.UpdateBalance(ctx, userID, 500.00); err != nil {\n\t\tlog.Fatalf("Update failed: %v", err)\n\t}\n\n\t// Проверяем, что кэш гарантированно пуст\n\texists, _ := rdb.Exists(ctx, key).Result()\n\tfmt.Printf("Ключ в кэше после инвалидации: %d (0 = отсутствует, грязное чтение исключено!)\\n", exists)\n}', 'note': 'Синхронная инвалидация кэша для предотвращения грязного чтения'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# До операции в кэше: 1000.00 руб.\n# [PostgreSQL] UPDATE accounts SET balance = balance + 500.00 WHERE user_id = 902\n# [Redis] Кэш баланса пользователя 902 успешно удален (удалено ключей: 1)\n# Ключ в кэше после инвалидации: 0 (0 = отсутствует, грязное чтение исключено!)'}], 'under_the_hood': 'Вызов `DEL` удаляет ключ немедленно, так что любой следующий запрос от микросервисов неизбежно пойдет в PostgreSQL и считает свежее актуальное значение баланса.', 'pitfalls': 'Делать `SET cacheKey newBalance` вместо `DEL`. Если между UPDATE в БД и записью в кэш пройдет миллисекунда, параллельный поток может перетереть кэш старым значением. Удаление (`DEL`) всегда безопаснее обновления!', 'bigtech_interview': '**Вопрос с собеседования:** «Почему в HighLoad финтехе удаление ключа из кэша предпочтительнее его обновления при изменении данных?»\n**Ответ:** 1. **Защита от состояния гонки (Race Condition):** два одновременных `UPDATE` могут записать в кэш данные в обратном порядке. 2. **Экономия ресурсов (Lazy Evaluation):** не тратится время на повторный расчет и сериализацию данных, которые могут больше не понадобиться. 3. **Простота восстановления:** удаленный ключ гарантированно приводит к штатному чтению истины из PostgreSQL.'}]
